function bpFromNow(targetMs, now) {
  const n = Number.isFinite(now) ? now : Date.now();
  const diff = Number(targetMs) - n;
  if (!Number.isFinite(diff)) return "";
  const ms = Math.abs(diff);
  const seconds = Math.round(ms / 1e3),
    minutes = Math.round(ms / 6e4),
    hours = Math.round(ms / 36e5);
  let days = Math.round(ms / 864e5),
    months = 0,
    years = 0;
  if (days >= 26) {
    const a = new Date(Math.min(n, n + diff)),
      b = new Date(Math.max(n, n + diff));
    const addM = (d, k) => {
      const x = new Date(d.getTime());
      const dd = x.getDate();
      x.setDate(1);
      x.setMonth(x.getMonth() + k);
      x.setDate(
        Math.min(dd, new Date(x.getFullYear(), x.getMonth() + 1, 0).getDate()),
      );
      return x;
    };
    let mon =
      (b.getFullYear() - a.getFullYear()) * 12 + (b.getMonth() - a.getMonth());
    if (addM(a, mon) > b) mon -= 1;
    const restDays = (b - addM(a, mon)) / 864e5;
    const monthsF = mon + (restDays * 4800) / 146097;
    days = Math.round(Math.round((mon * 146097) / 4800) + restDays);
    months = Math.round(monthsF);
    years = Math.round(monthsF / 12);
  }
  const t =
    seconds <= 44
      ? "a few seconds"
      : seconds < 45
        ? `${seconds} seconds`
        : minutes <= 1
          ? "a minute"
          : minutes < 45
            ? `${minutes} minutes`
            : hours <= 1
              ? "an hour"
              : hours < 22
                ? `${hours} hours`
                : days <= 1
                  ? "a day"
                  : days < 26
                    ? `${days} days`
                    : months <= 1
                      ? "a month"
                      : months < 11
                        ? `${months} months`
                        : years <= 1
                          ? "a year"
                          : `${years} years`;
  return diff > 0 ? `in ${t}` : `${t} ago`;
}
