function liveInplayMultiSport() {
  if (shouldFetchCricketEvents()) {
    refreshCricketEventsFromApi()
      .then(render)
      .catch((error) => {
        state.message = feedMsg(error, "Cricket feed unavailable");
        render();
      });
  }
  if (shouldFetchSports())
    refreshSportEventsFromApi()
      .then(render)
      .catch(() => {});
  const cricketRows = cricketFeedRows({ inplayOnly: true });
  const soccerInplay = (state.soccerEvents || []).filter(isSportEventInplay);
  const tennisInplay = (state.tennisEvents || []).filter(isSportEventInplay);
  const section = (
    iconKey,
    name,
    body,
  ) => `<section class="sports-table user-market-table sport-page-table inplay-sport">
    <div class="sport-heading section-heading"><strong><span class="sport-heading-icon">${sidebarSvgIcon(iconKey)}</span>${escapeHtml(T(name))}</strong><span>${escapeHtml(T("col:Matched"))}</span><span>1</span><span>X</span><span>2</span></div>
    ${body}
  </section>`;
  return (
    section(
      "Cricket",
      "Cricket",
      cricketRows.map(cricketDashboardRow).join(""),
      true,
    ) +
    section(
      "Soccer",
      "Football",
      soccerInplay.map((e) => sportDashboardRow(e, "Soccer", true)).join(""),
      true,
    ) +
    section(
      "Tennis",
      "Tennis",
      tennisInplay.map((e) => sportDashboardRow(e, "Tennis", false)).join(""),
      false,
    )
  );
}
