function rulesCacheKey(kind) {
  return kind + "|" + (state.lang || "en");
}
function openRulesModal(kind) {
  state.rulesModal = kind;
  state.rulesHtml = state.rulesHtml || {};
  const key = rulesCacheKey(kind);
  if (!state.rulesHtml[key]) {
    const file = kind === "marketRules" ? "market-rules.html" : "tos.html";
    fetch(`/assets/${file}?v=${Date.now()}`)
      .then((r) => {
        if (!r.ok) throw new Error("missing");
        return r.text();
      })
      .then((html) => {
        state.rulesHtml[key] = html;
        render();
        if (state.lang !== "ar" || kind !== "marketRules") return;
        fetch(`/assets/market-rules.ar.html?v=${Date.now()}`)
          .then((r) => (r.ok ? r.text() : ""))
          .then((ar) => {
            if (!ar || state.rulesHtml[key] !== html) return;
            state.rulesHtml[key] =
              html +
              `<hr class="mr-langsep" /><h5 class="mr-h mr-arhead" dir="rtl">${escapeHtml(T("Market Rules"))}</h5><div class="mr-ar" dir="rtl" lang="ar">${ar}</div>`;
            render();
          })
          .catch(() => {});
      })
      .catch(() => {
        state.rulesModal = null;
        render();
      });
  }
  render();
}
