function bpUserSearchMerge(q, localNames, drop) {
  const seq = ++_bpUsmSeq;
  getJson(`/api/user-suggest?q=${encodeURIComponent(q)}`)
    .then((d) => {
      if (seq !== _bpUsmSeq || !drop) return;
      const have = new Set(
        (localNames || []).map((n) => String(n).toLowerCase()),
      );
      const extra = ((d && d.users) || []).filter(
        (u) => !have.has(String(u.username).toLowerCase()),
      );
      const all = [
        ...(localNames || []).map((n) => ({ username: n })),
        ...extra,
      ];
      const lq = String(q || "").toLowerCase();
      all.sort(
        (a, b) =>
          (String(a.username).toLowerCase().startsWith(lq) ? 0 : 1) -
            (String(b.username).toLowerCase().startsWith(lq) ? 0 : 1) ||
          String(a.username).length - String(b.username).length,
      );
      const list = all.slice(0, 12);
      drop.innerHTML = list.length
        ? list
            .map(
              (a) =>
                `<button type="button" class="usd-item" onmousedown='selectUserSearch(${JSON.stringify(a.username).replace(/'/g, "&#39;")})'>${escapeHtml(a.username)}${a.role ? `<small style="float:right;color:var(--bp-muted)">${escapeHtml(a.role)}</small>` : ""}</button>`,
            )
            .join("")
        : `<div class="usd-empty">No user</div>`;
      drop.classList.add("open");
    })
    .catch(() => {});
}
