    return `<span class="search-none">No user found</span>`;
  const acc =
    findAccountAnywhere(state.searchResult) ||
    (state.currentAccount && state.currentAccount.id === state.searchResult
      ? state.currentAccount
      : null);
  if (!acc) return "";
  const chain = accountAncestry(acc);
  const meId = String((state.currentAccount && state.currentAccount.id) || "");
  const crumbAction = (a) => {
    const id = String(a.id || "");
    if (id && id === meId) return `clearDealerScope()`;
    if (accountGroup(a) === "dealers")
      return `openDealerScope(${JSON.stringify(id)})`;
    return `selectUserSearch(${JSON.stringify(a.username)})`;
  };
  const crumb = chain
    .map(
      (a, i) =>
        `<button type="button" class="search-crumb${i === chain.length - 1 ? " cur" : ""}"${accountGroup(a) === "dealers" ? ` title="${escapeHtml(a.username)} ka page kholein"` : ""} onclick='${crumbAction(a).replace(/'/g, "&#39;")}'>${escapeHtml(a.username)}</button>`,
    )
