function fancyBookModalHtml() {
  const session = state.fancyBook;
  if (!session) return "";
  const ladder = fancySessionLadder((currentUser() || {}).username, session);
  const numF = (n) => (n < 0 ? `-${formatMoney(Math.abs(n))}` : formatMoney(n));
  const body = ladder.length
    ? ladder
        .map(
          (row) =>
            `<tr><td>${row.score}</td><td class="${row.position < 0 ? "fb-neg" : "fb-pos"}">${numF(row.position)}</td></tr>`,
        )
        .join("")
    : `<tr><td colspan="2" class="fb-empty">No position on this session yet</td></tr>`;
  return `<div class="fancy-book-overlay" onclick="closeFancyBook()">
    <div class="fancy-book-card" onclick="event.stopPropagation()">
      <div class="fancy-book-head"><strong>${escapeHtml(session)}</strong><button class="fancy-book-x" type="button" onclick="closeFancyBook()">&times;</button></div>
      <table class="fancy-book-table"><thead><tr><th>Score</th><th>Position</th></tr></thead><tbody>${body}</tbody></table>
      <div class="fancy-book-foot"><button class="fancy-book-close" type="button" onclick="closeFancyBook()">Close</button></div>
    </div>
  </div>`;
}
function fancyNameCellHtml(sessionName) {
  const book = fancySessionBook((currentUser() || {}).username, sessionName);
  const hasBook = book.low !== 0 || book.high !== 0;
  const numF = (n) => (n < 0 ? `-${formatMoney(Math.abs(n))}` : formatMoney(n));
  const pos = hasBook
    ? `<b class="${book.low < 0 ? "mp-neg" : "mp-pos"}">${numF(book.low)}</b> <b class="${book.high < 0 ? "mp-neg" : "mp-pos"}">${numF(book.high)}</b> `
    : "";
  return `<strong class="fancy-name" style="display:flex;flex-direction:column;align-items:flex-start;justify-content:center;line-height:1.25;">
    <span>${escapeHtml(sessionName)}</span>
    <span class="fancy-book-row">${pos}<a class="fancy-book-link" href="#" onclick='openFancyBook(${JSON.stringify(sessionName)});return false;'>Book</a></span>
  </strong>`;
}
function cricketSingleSessionBlock(fancyMarkets, sessionName) {
  const target = canonicalSessionName(sessionName).toLowerCase();
  const userFancyMax = myEffectiveLimit("fancy");
  const wrap = (
    titleName,
    maxBet2,
    inner,
  ) => `<section class="cricket-market-block">
    <div class="cricket-market-title"><span class="market-ball"><svg class="mb-clock" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="13" r="7"/><path d="M12 9.5v3.6l2.4 1.5"/><path d="M9.4 3h5.2"/><path d="M18 7l1.6-1.6"/></svg></span><strong>${escapeHtml(String(titleName))} ${cricketMaxBetTag(maxBet2)}</strong><button class="market-user-icon" aria-label="Info">i</button><b>Back</b><b>Lay</b></div>
    ${inner}
  </section>`;
  for (const market of fancyMarkets) {
    const rows =
      Array.isArray(market?.rows) && market.rows.length
        ? market.rows
        : [market];
    const row = rows.find((entry) => {
      const name = fancySessionName(entry, market);
      return name && name.toLowerCase() === target;
    });
    if (row) {
      const name =
        fancySessionName(row, market) || canonicalSessionName(sessionName);
      const maxBet2 =
        userFancyMax > 0
          ? abbrevAmount(userFancyMax)
          : String(market?.maxBet || "");
      return wrap(name, maxBet2, cricketFancyRowHtml(row, market));
    }
  }
  const maxBet = userFancyMax > 0 ? abbrevAmount(userFancyMax) : "";
  return wrap(
    sessionName,
    maxBet,
    `<div class="cricket-market-row fancy suspended">${fancyNameCellHtml(sessionName)}<div>SUSPENDED</div></div>`,
  );
}
function exposureForUser(username) {
  const grouped = new Map();
  state.bets
    .filter((bet) => bet.user === username && bet.status === "active")
    .forEach((bet) => {
      const mktKey = String(
        bet.marketId || (bet.isFancy ? (bet.selection ?? "") : ""),
      );
      const key = `${bet.event}:${bet.market}:${mktKey}`;
      if (!grouped.has(key)) grouped.set(key, []);
      grouped.get(key).push(bet);
    });
  let exposure = 0;
  grouped.forEach((bets) => {
    exposure += sportsWorstCase(
      bets,
      groupTotalRunners(bets, bets[0].sport, bets[0].market),
    );
  });
  return exposure;
}
function syncAccountExposure(username) {
  const account = state.users.find((user) => user.username === username);
  if (account) account.exposure = exposureForUser(username);
}
