async function applyCashCredit(
  group,
  id,
  wallet,
  direction,
  amountValue,
  noteValue,
) {
  const account = findAccount(group, id);
  if (!account) return { ok: false, message: "Account not found" };
  const amount = Math.max(0, Number(amountValue) || 0);
  if (!(amount > 0)) return { ok: false, message: "Pehle raqam likhein" };
  const note = String(noteValue || "C button");
  if (account.totalCreditGiven === void 0) {
    account.totalCreditGiven = num(account.credit);
  }
  if (account.totalDeposited === void 0) {
    account.totalDeposited = Math.max(num(account.cash), 0);
  }
  if (account.totalWithdrawn === void 0) {
    account.totalWithdrawn = 0;
  }
  if (direction === "deposit") {
    const mmc =
      account.metrics && account.metrics.modal && account.metrics.modal.credit;
    const hasServerLimit =
      Boolean(mmc) && Object.prototype.hasOwnProperty.call(mmc, "creditLimit");
    const maxDeposit = hasServerLimit
      ? mmc.creditLimit == null
        ? Number.POSITIVE_INFINITY
        : num(mmc.creditLimit)
      : wallet === "cash"
        ? maxCashDeposit(account)
        : maxCreditDeposit();
    const walletLabel = wallet === "credit" ? "credit" : "cash";
    if (Number.isFinite(maxDeposit) && toMinor(amount) > maxDeposit) {
      return {
        ok: false,
        message: `Max ${walletLabel} deposit is ${money(maxDeposit)}`,
      };
    }
  }
  if (direction === "withdraw" && wallet === "cash") {
    const mm =
      account.metrics && account.metrics.modal && account.metrics.modal.cash;
    const limit = mm
      ? account.role === "bettor"
        ? isBetproOwner() || !(num(mm.bonusLien) > 0)
          ? maxDealerCashMinus(account)
          : num(mm.maxWithdraw)
        : num(mm.maxWithdraw)
      : account.role === "bettor"
        ? maxDealerCashMinus(account)
        : maxCashWithdraw(account);
    if (amount > limit)
      return {
        ok: false,
        message: `Cannot withdraw more than ${money(limit)} cash`,
      };
  }
  if (direction === "withdraw" && wallet === "credit") {
    const mmw =
      account.metrics && account.metrics.modal && account.metrics.modal.credit;
    const avail =
      mmw && mmw.availableBal != null
        ? num(mmw.availableBal)
        : num(account.credit);
    const creditMax = Math.max(0, Math.min(avail, num(account.credit)));
    if (amount > creditMax)
      return {
        ok: false,
        message: `Cannot withdraw more than ${money(creditMax)} credit`,
      };
  }
  const _res = await postJson("/api/db/wallet-adjust", {
    userId: id,
    wallet,
    direction,
    amount,
    description: note,
  });
  await refreshAccountsFromDb();
  return {
    ok: true,
    message: `${account.username} ${wallet} ${direction} saved`,
    txnId: (_res && _res.transaction && _res.transaction.id) || "",
  };
}
async function submitCashCredit(event, group, id) {
  event.preventDefault();
  const data = new FormData(event.currentTarget);
  let result;
  try {
    result = await applyCashCredit(
      group,
      id,
      data.get("wallet"),
      data.get("direction"),
      data.get("amount"),
      data.get("description") || data.get("note"),
    );
  } catch (error) {
    result = { ok: false, message: error.message };
  }
  if (!result.ok) {
    flash(result.message);
    return;
  }
  closeModal();
  flash(result.message);
  openLedgerPopup(
    id,
    group,
    data.get("wallet") === "credit" ? "credit" : "",
    result.txnId || true,
  );
}
