function settlePageUrl(id) {
  return `${routePaths.settlePl}?UserId=${encodeURIComponent(String(id))}`;
}
function openSettlePopup(id, group = "dealers") {
  const w = window.open(
    settlePageUrl(id),
    `bpexch_settle_${id}`,
    "height=800,width=900,titlebar=0,menubar=0,resizable=yes,scrollbars=yes",
  );
  if (!w) {
    state.settleCtx = { id: String(id) };
    state.modal = { type: "settle", id, group };
    render();
    return;
  }
  try {
    w.focus();
  } catch (e) {}
}
function _settleCtx(id) {
  if (!state.settleCtx || String(state.settleCtx.id) !== String(id))
    state.settleCtx = { id: String(id) };
  return state.settleCtx;
}
function _settleLoad(ctx) {
  if (ctx.loading) return;
  ctx.loading = true;
  getJson(`/api/admin/pl-settle-figures?dealerId=${encodeURIComponent(ctx.id)}`)
    .then((data) => {
      ctx.fig = data;
      ctx.loadErr = "";
    })
    .catch((e) => {
      ctx.loadErr = e.message || "Load failed";
    })
    .finally(() => {
      ctx.loading = false;
      ctx.loaded = true;
      render();
    });
}
function settleKeep(el) {
  const ctx = state.settleCtx;
  if (!ctx || !el) return;
  if (el.name === "amount") ctx.amount = el.value;
  else if (el.name === "description") ctx.desc = el.value;
}
function settleCardHtml(id) {
  const ctx = _settleCtx(id);
  if (!ctx.loaded && !ctx.loading) _settleLoad(ctx);
  const f = ctx.fig || null;
  const max = f ? `${f.maxText} ${f.unit}` : "";
  const msg = ctx.msg || ctx.loadErr || "";
  const amount = ctx.amount == null ? "0.00" : ctx.amount;
  const desc = ctx.desc == null ? "P/L to Cash transfer" : ctx.desc;
  return `<div class="sp-card"><div class="sp-head">Settle P/L Account</div><div class="sp-body"><p class="sp-msg"><strong>${escapeHtml(msg)}</strong></p><form method="post" onsubmit="settleSubmit(event)"><div class="sp-group"><label for="spAmount">Amount</label><input class="sp-input" id="spAmount" name="amount" type="text" inputmode="decimal" autocomplete="off" value="${escapeHtml(amount)}" oninput="settleKeep(this)"><small class="sp-help">Max amount to transfer: ${escapeHtml(max)}</small><br><label for="spDesc">Description</label><input class="sp-input" id="spDesc" name="description" type="text" maxlength="120" autocomplete="off" value="${escapeHtml(desc)}" oninput="settleKeep(this)"><div class="sp-submit"><button class="sp-btn" type="submit" ${ctx.busy ? "disabled" : ""}><strong>Submit</strong></button></div></div></form></div></div>`;
}
function settlePopupView() {
  const id = (state.settleCtx && state.settleCtx.id) || "";
  return `<main class="settle-pop"><div class="sp-wrap">${settleCardHtml(id)}</div></main>`;
}
async function settleSubmit(event) {
  event.preventDefault();
  const ctx = state.settleCtx;
  if (!ctx || ctx.busy) return;
  const form = event.currentTarget;
  const raw = String(form.elements.amount.value || "").trim();
  const desc = String(form.elements.description.value || "");
  ctx.amount = raw;
  ctx.desc = desc;
  const n = Number(raw.split(",").join(""));
  if (raw === "" || !Number.isFinite(n)) {
    ctx.msg = "The field TransferAmount must be a number.";
    render();
    return;
  }
  if (!window.confirm("Transfer this amount from P/L account to cash account?"))
    return;
  ctx.busy = true;
  render();
  let done = false;
  try {
    await postJson("/api/admin/pl-settle", {
      dealerId: ctx.id,
      kind: "pl",
      amount: Math.abs(n),
      description: desc,
    });
    ctx.msg = `Success. ${raw} was moved to cash account.`;
    done = true;
  } catch (error) {
    ctx.msg = error.message || "Failed";
  }
  ctx.busy = false;
  ctx.loaded = false;
  render();
  if (!done) return;
  if (state.standaloneSettle) {
    try {
      const op = window.opener;
      if (op && !op.closed && typeof op.refreshAccountsFromDb === "function")
        op.refreshAccountsFromDb()
          .then(() => {
            try {
              op.render();
            } catch (e) {}
          })
          .catch(() => {});
    } catch (e) {}
  } else {
    refreshAccountsFromDb()
      .then(render)
      .catch(() => {});
  }
}
async function toggleAccount(group, id) {
  const account = findAccount(group, id);
  const makeActive = !isAccountActive(account);
  try {
    await patchJson(`/api/db/users/${encodeURIComponent(id)}`, {
      active: makeActive,
    });
    await refreshAccountsFromDb();
  } catch (error) {
    flash(error.message || "Update failed");
    return;
  }
  flash(`${account.username} ${makeActive ? "activated" : "deactivated"}`);
  render();
}
