function handleInviteRegister(event) {
  event.preventDefault();
  const inv = state.invite;
  if (!inv || !inv.token) return;
  const f = event.target;
  const btn = f.querySelector("button[type=submit]");
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Bana rahe hain\u2026";
  }
  fetch(`/api/invite/${inv.code}/register`, {
    method: "POST",
    headers: { "content-type": "application/json", accept: "application/json" },
    body: JSON.stringify({
      token: inv.token,
      username: String(f.username.value || ""),
      password: String(f.password.value || ""),
    }),
  })
    .then(async (r) => {
      const d = await r.json().catch(() => ({}));
      if (!r.ok) {
        state.invite = {
          ...inv,
          err: d.error || "Koshish dobara karein",
          u: String(f.username.value || ""),
          pw: String(f.password.value || ""),
        };
        render();
        try {
          const el = document.querySelector(
            "#invite-panel input[name=username]",
          );
          if (el) {
            el.focus();
            el.select();
          }
        } catch (e) {}
        return;
      }
      const u = String(f.username.value || ""),
        pw = String(f.password.value || "");
      state.invite = { ...inv, sent: true, err: "", u: "", pw: "" };
      try {
        if (
          window.PasswordCredential &&
          navigator.credentials &&
          navigator.credentials.store
        ) {
          await navigator.credentials.store(
            new window.PasswordCredential({ id: u, password: pw, name: u }),
          );
        }
      } catch (e) {}
      try {
        await loginWithCredentials(u, pw);
      } catch (e) {}
      render();
    })
    .catch(() => {
      state.invite = { ...inv, err: "Network \u2014 dobara koshish karein" };
      render();
    });
}
