function resultMarketLabel(raw) {
  const t = String(raw || "").trim();
  if (!t) return "-";
  const ou = t.match(/^OVER[_\s-]?UNDER[_\s-]?(\d)(\d)$/i);
  if (ou) return `Over/Under ${ou[1]}.${ou[2]} Goals`;
  const set = t.match(/^SET[_\s-]?(\d+)[_\s-]?WINNER$/i);
  if (set) return `Set ${set[1]} Winner`;
  const map = {
    MATCH_ODDS: "Match Odds",
    BOOKMAKER: "Bookmaker",
    TIED_MATCH: "Tied Match",
    COMPLETED_MATCH: "Completed Match",
    TO_WIN_THE_TOSS: "Toss",
    SET_BETTING: "Set Betting",
    NUMBER_OF_SETS: "Number Of Sets",
    EACH_WAY: "Each Way",
    OTHER_PLACE: "Other Place",
  };
  return map[t.toUpperCase()] || t;
}
