const RR_TABS = [
  ["soccer", "Soccer", 1, "football"],
  ["tennis", "Tennis", 2, "tennis"],
  ["cricket", "Cricket", 4, "cricket"],
  ["horse", "Horse Race", 7, "horse_racing"],
  ["fancy", "Fancy", 8, "fancy"],
  ["casino", "Casino", 12, "casino"],
  ["greyhound", "Greyhound", 4339, "greyhound"],
];
const RR_MIN_DATE = new Date(2026, 0, 1, 0, 0, 0, 0).getTime();
const RR_MAX_ROWS = 1e3;
const RR_COLS = ["", "Match name", "Market Name", "Date", "Result"];
function rrState() {
  if (!state.rr) {
    const now = new Date();
    const todayUtc = Date.UTC(
      now.getUTCFullYear(),
      now.getUTCMonth(),
      now.getUTCDate(),
    );
    let tab = "soccer";
    try {
      const id = Number(new URLSearchParams(window.location.search).get("id"));
      const t = RR_TABS.find((x) => x[2] === id);
      if (t) tab = t[0];
    } catch {}
    state.rr = {
      tab,
      from: todayUtc - 4 * 864e5,
      to: todayUtc + 864e5 - 1e3,
      len: 50,
      search: "",
      page: 0,
      order: [3, "desc"],
      open: {},
      hidden: [],
      picker: null,
    };
    state.rr.applied = { from: state.rr.from, to: state.rr.to };
  }
  return state.rr;
}
const rrPad = (n) => String(n).padStart(2, "0");
function rrLocalText(ms) {
  const d = new Date(ms);
  const h = d.getHours();
  return `${rrPad(d.getMonth() + 1)}/${rrPad(d.getDate())}/${d.getFullYear()} ${h % 12 || 12}:${rrPad(d.getMinutes())} ${h < 12 ? "AM" : "PM"}`;
}
function rrParseLocal(text) {
  const m = String(text || "")
    .trim()
    .match(
      /^(\d{1,2})\/(\d{1,2})\/(\d{4})(?:\s+(\d{1,2}):(\d{2})\s*([AaPp][Mm])?)?$/,
    );
  if (!m) return NaN;
  let h = Number(m[4] || 0);
  const ap = (m[6] || "").toUpperCase();
  if (ap === "PM" && h < 12) h += 12;
  if (ap === "AM" && h === 12) h = 0;
  return new Date(
    Number(m[3]),
    Number(m[1]) - 1,
    Number(m[2]),
    h,
    Number(m[5] || 0),
    0,
    0,
  ).getTime();
}
function rrUtcText(ms) {
  const d = new Date(ms);
  const h = d.getUTCHours();
  return `${d.getUTCMonth() + 1}/${d.getUTCDate()}/${d.getUTCFullYear()} ${h % 12 || 12}:${rrPad(d.getUTCMinutes())}:${rrPad(d.getUTCSeconds())} ${h < 12 ? "AM" : "PM"}`;
}
const rrOrdinal = (n) => {
  const v = n % 100;
  return (
    n + (v >= 11 && v <= 13 ? "th" : ["th", "st", "nd", "rd"][n % 10] || "th")
  );
};
function rrDataKey(s) {
  return [s.tab, s.applied.from, s.applied.to].join("|");
}
function rrRetry() {
  state.rrCache = {};
  state.rrFetching = null;
  render();
}
function rrEnsureData() {
  const s = rrState();
  const tab = RR_TABS.find((t) => t[0] === s.tab) || RR_TABS[0];
  const key = rrDataKey(s);
  state.rrCache = state.rrCache || {};
  if (state.rrCache[key]) return state.rrCache[key];
  if (state.rrFetching === key) return { rows: [], loading: true };
  state.rrFetching = key;
  const dayUtc = (ms) => new Date(ms).toISOString().slice(0, 10);
  const src = tab[3];
  const rng = { from: s.applied.from, to: s.applied.to };
  const load =
    src === "casino"
      ? rrLoadCasino(rng)
      : src === "fancy"
        ? rrLoadFancy(rng, dayUtc)
        : rrLoadRelay(rng, src, dayUtc);
  load
    .then((rows) => {
      const inRange = rows.filter(
        (r) => Number.isFinite(r.t) && r.t >= rng.from && r.t <= rng.to,
      );
      inRange.sort((a, b) => b.t - a.t);
      state.rrCache[key] = {
        rows: inRange.slice(0, RR_MAX_ROWS),
        loading: false,
      };
    })
    .catch(() => {
      state.rrCache[key] = { rows: [], loading: false, error: true };
    })
    .finally(() => {
      if (state.rrFetching === key) state.rrFetching = null;
      render();
    });
  return { rows: [], loading: true };
}
async function rrLoadRelay(s, sport, dayUtc) {
  const evs = [];
  for (let page = 1; page <= 10; page++) {
    const qs = new URLSearchParams({
      sport,
      from: dayUtc(s.from),
      to: dayUtc(s.to),
      page: String(page),
      limit: "200",
    });
    const data = await getJson(`/api/results-list?${qs}`);
    const list = Array.isArray(data.results) ? data.results : [];
    for (const ev of list)
      if (!ev.sport || String(ev.sport) === sport) evs.push(ev);
    if (
      !list.length ||
      page * 200 >= (Number(data.total) || 0) ||
      evs.length >= RR_MAX_ROWS * 2
    )
      break;
  }
  const out = [];
  for (const ev of rrDedupeRaces(evs, sport))
    out.push(...rrRowsFromEvent(ev, sport));
  const soon = Date.now() + 6e4;
  return out.filter((r) => !(r.t > soon));
}
function rrDedupeRaces(evs, sport) {
  if (sport !== "horse_racing" && sport !== "greyhound") return evs;
  const bad = (ev) =>
    / Match /.test(String(ev.event_name || "")) ||
    !/-m\d/.test(String(ev.event_id || ""));
  const best = new Map();
  for (const ev of evs) {
    const base = String(ev.event_id || "").replace(/-m\d.*$/, "");
    const cur = best.get(base);
    if (!cur || (bad(cur) && !bad(ev))) best.set(base, ev);
  }
  return [...best.values()].filter((ev) => !bad(ev));
}
function rrRowsFromEvent(ev, sport) {
  const racing = sport === "horse_racing" || sport === "greyhound";
  const markets =
    Array.isArray(ev.markets) && ev.markets.length
      ? ev.markets
      : [{ market_type: ev.market_type, winner_name: ev.winner_name }];
  const t = Date.parse(ev.created_at);
  const rows = [];
  for (const m of markets) {
    const type = String(m.market_type || "");
    const winner = String(m.winner_name == null ? "" : m.winner_name).trim();
    if (!winner || winner === "\u2014" || winner === "-") continue;
    if (/^fancy$/i.test(type)) continue;
    if (racing && /place|each.?way/i.test(type)) continue;
    rows.push({
      name: racing
        ? rrRaceName(ev.event_name, ev.event_id, rrRaceStart(ev))
        : String(ev.event_name || ev.event_id || ""),
      market: racing ? rrRaceMarket(ev, type) : resultMarketLabel(type),
      t,
      result: winner,
    });
  }
  return rows;
}
const RR_RACE_CC = {
  AU: "AUS",
  FR: "FRA",
  ZA: "RSA",
  NZ: "NZL",
  US: "US",
  GB: "",
  IE: "",
};
const RR_RACE_TZ = {
  AU: "Australia/Sydney",
  NZ: "Pacific/Auckland",
  US: "America/New_York",
  GB: "Europe/London",
  IE: "Europe/Dublin",
  FR: "Europe/Paris",
  ZA: "Africa/Johannesburg",
};
function rrRaceName(raw, eventId, startMs) {
  let name = String(raw || "")
    .replace(/\s+/g, " ")
    .trim();
  const cc = (String(eventId || "").match(/^(?:7|4339)-([A-Z]{2})-/) || [])[1];
  name = name.replace(/\s*\(([A-Z]{2,3})\)/, (m, c) => {
    const k = RR_RACE_CC[c] != null ? RR_RACE_CC[c] : c;
    return k ? ` (${k})` : "";
  });
  let day = null,
    mon = null;
  if (cc && RR_RACE_TZ[cc] && Number.isFinite(startMs)) {
    try {
      const parts = new Intl.DateTimeFormat("en-US", {
        timeZone: RR_RACE_TZ[cc],
        day: "numeric",
        month: "short",
      }).formatToParts(new Date(startMs));
      day = Number((parts.find((x) => x.type === "day") || {}).value) || null;
      mon = (parts.find((x) => x.type === "month") || {}).value || null;
    } catch {}
  }
  return name.replace(
    /\b(\d{1,2}) ([A-Z][a-z]{2})$/,
    (m, d, mo) => `${rrOrdinal(day || Number(d))} ${mon || mo}`,
  );
}
function rrRaceStart(ev) {
  const m = String(ev.event_id || "").match(/(\d{4}-\d{2}-\d{2}T[\d:.]+Z)/);
  return m ? Date.parse(m[1]) : Date.parse(ev.created_at);
}
function rrRaceMarket(ev, type) {
  const known = state.raceNames && state.raceNames[String(ev.event_id)];
  return known ? String(known) : resultMarketLabel(type);
}
async function rrLoadFancy(s, dayUtc) {
  const out = [];
  for (let page = 1; page <= 4; page++) {
    const qs = new URLSearchParams({
      from: dayUtc(s.from - 864e5),
      to: dayUtc(s.to + 864e5),
      page: String(page),
      limit: "500",
    });
    const data = await getJson(`/api/fancy-results-log?${qs}`);
    const list = Array.isArray(data.rows) ? data.rows : [];
    for (const r of list) {
      const t0 = Date.parse(r.date);
      out.push({
        name: String(r.name || ""),
        market: String(r.market || ""),
        t: Number.isFinite(t0) ? Math.floor(t0 / 6e4) * 6e4 : NaN,
        result: String(r.result == null ? "" : r.result).replace(
          /^Score:\s*/i,
          "",
        ),
      });
    }
    if (!list.length || page * 500 >= (Number(data.total) || 0)) break;
  }
  return out;
}
