  if (!src || !src.innerHTML.trim()) return hideRaceTipFloat();
  const el = ensureRaceTipFloat();
  el.innerHTML = src.innerHTML;
  el.classList.add("on");
  const b = runnerEl.getBoundingClientRect();
  const fw = el.offsetWidth,
    fh = el.offsetHeight;
  el.style.left =
    Math.max(4, Math.min(b.left, window.innerWidth - fw - 4)) + "px";
