function cricketOwnFigureBlocks(profile) {
  const list = (profile && profile.figureMarkets) || [];
  if (!list.length) return "";
  return list
    .map((fm) => {
      const mine = (state.bets || []).filter(
        (b) => String(b.marketId || "") === String(fm.id),
      );
      const openMine = mine.filter((b) =>
        ["active", "open"].includes(String(b.status || "").toLowerCase()),
      );
      const bookFor = (d) =>
        openMine.reduce(
          (s, b) =>
            s +
            (Math.trunc(Number(b.selection)) === d
              ? Number(b.potential) || 0
              : -(Number(b.stake) || 0)),
          0,
        );
      const suspended = fm.status === "suspended";
      const settledDigit =
        fm.status === "settled" ? Math.trunc(Number(fm.winningDigit)) : null;
      const clickable = fm.status === "open";
      const box = (d) => {
        const book = openMine.length ? bookFor(d) : null;
        const isWin = settledDigit === d;
        const mods = `${suspended ? "opacity:.45;" : ""}cursor:${clickable ? "pointer" : "default"};`;
        const winMod = isWin
          ? "outline:3px solid #0b6121;outline-offset:-3px;"
          : "";
        const picked =
          clickable &&
          state.selectedBet &&
          String(state.selectedBet.marketId || "") === String(fm.id) &&
          String(state.selectedBet.runner) === String(d)
            ? "outline:2px solid #14222f;"
            : "";
        const inner = `<span class="fig-own-cell" style="${winMod}${picked}"><span style="font-weight:800;font-size:20px;color:#273a47">${d}</span><small style="font-size:13px;color:#273a47">8.85</small></span>
        <span class="fig-own-book" style="color:${(book || 0) < 0 ? "#ff0000" : "#0b6121"}">${book != null && book !== 0 ? formatMoney(book) : isWin ? "WIN" : ""}</span>`;
        return clickable
          ? `<button class="fig-own-box" style="${mods}" onclick='selectBet(${JSON.stringify(String(d))},"BACK",8.85,"","","","figure_market",${JSON.stringify(fm.id)},${JSON.stringify(fm.name)})'>${inner}</button>`
          : `<span class="fig-own-box" style="${mods}">${inner}</span>`;
      };
      const tag =
        fm.status === "settled"
          ? ` \u2014 SETTLED (Digit ${settledDigit})`
          : suspended
            ? " \u2014 SUSPENDED"
            : "";
      const rowsHtml = `<div class="fig-own-grid">
      <div class="fig-own-row">${[0, 1, 2, 3, 4].map(box).join("")}</div>
      <div class="fig-own-row">${[5, 6, 7, 8, 9].map(box).join("")}</div>
    </div>`;
      return `<section class="cricket-market-block">
      <div class="cricket-market-title"><span class="market-ball"><svg class="mb-clock" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="13" r="7"/><path d="M12 9.5v3.6l2.4 1.5"/><path d="M9.4 3h5.2"/><path d="M18 7l1.6-1.6"/></svg></span><strong>${escapeHtml(fm.name)}${escapeHtml(tag)} ${cricketMaxBetTag(abbrevAmount(myEffectiveLimit("figure") || 1e5))}</strong><button class="market-user-icon" aria-label="Info">i</button></div>
      ${rowsHtml}
    </section>`;
    })
    .join("");
}
