function raceRulesBtnHtml(market) {
  const isPlace =
    /PLACE/i.test(String((market && market.marketType) || "")) ||
    /to\s+be\s+placed/i.test(
      String((market && (market.marketName || market.title)) || ""),
    );
  const kind = !isHorseRacingNow() ? "greyhound" : isPlace ? "place" : "win";
  return `<button type="button" class="market-user-icon race-rules-btn" aria-label="Rules" onclick="openRaceMarketRules('${kind}')"><span class="rr-t">RULES</span></button>`;
}
function marketInfoBtnHtml(market) {
  const cat = matchPageLimitCat();
  const t = String((market && market.marketType) || "")
    .toUpperCase()
    .replace(/\s+/g, "_");
  const nm = String(
    (market && (market.marketName || market.title)) || "",
  ).trim();
  const isMo = t === "MATCH_ODDS" || /^match\s*odds$/i.test(nm);
  let kind = "";
  if (cat === "soccer")
    kind = isMo ? "soccerMo" : /^OVER_UNDER_[0-9]+$/.test(t) ? "soccerOu" : "";
  else if (cat === "cricket")
    kind = isMo || t.includes("TOSS") || /^toss$/i.test(nm) ? "cricketMo" : "";
  if (kind)
    return `<button type="button" class="market-user-icon race-rules-btn" aria-label="Rules" onclick="openRaceMarketRules('${kind}')"><span class="rr-t">RULES</span></button>`;
  return `<button class="market-user-icon" aria-label="Info">i</button>`;
}
function raceSuspendedBlock(market) {
  const displayTitle = getCricketMarketDisplayTitle(market);
  const maxBet = cricketMarketMaxBet(market);
  const rawMarketId = String(market?.marketId || "");
  const closed = isCricketMarketClosed(market);
  const statusLabel = closed ? "CLOSED" : "SUSPENDED";
  const rows = Array.isArray(market?.rows) ? market.rows : [];
  const bookBetsSusp = currentMatchMatchedBets("match_odds", rawMarketId);
  const isRemoved = (r) =>
    String((r && r.status) || "").toUpperCase() === "REMOVED";
  const ordered = rows
    .map((r, i) => [r, i])
    .sort(
      (a, b) =>
        (isRemoved(a[0]) ? 1 : 0) - (isRemoved(b[0]) ? 1 : 0) || a[1] - b[1],
    )
    .map((p) => p[0]);
  const titleHtml = `<div class="cricket-market-title"><span class="market-ball"><svg class="mb-clock" viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="13" r="7"/><path d="M12 9.5v3.6l2.4 1.5"/><path d="M9.4 3h5.2"/><path d="M18 7l1.6-1.6"/></svg></span><strong>${escapeHtml(displayTitle)} ${cricketMaxBetTag(maxBet)}</strong>${raceRulesBtnHtml(market)}<b>Back</b><b>Lay</b></div>`;
  const rowsHtml = ordered
    .map((raw) => {
      const runner =
        normalizeCricketRunner(raw) || normalizeCricketSelection(raw) || "";
      const number = raw && raw.number;
      const jockey = raw && raw.jockey;
      const selectionId = raw && raw.selectionId;
      const isWinner =
        String((raw && raw.status) || "").toUpperCase() === "WINNER";
      const removed = isRemoved(raw);
      const checked = raceSelectionFor(rawMarketId).includes(
        String(selectionId),
      );
      const _placeMkt =
        /PLACE/i.test(String((market && market.marketType) || "")) ||
        /to\s+be\s+placed/i.test(
          String((market && (market.marketName || market.title)) || ""),
        );
      const checkbox =
        isHorseRacingNow() && !_placeMkt
          ? `<input type="checkbox" class="race-check" ${checked ? "checked" : ""} onclick='event.stopPropagation();toggleRaceSelect(${JSON.stringify(rawMarketId)},${JSON.stringify(String(selectionId))})'>`
          : "";
      const nameCell = raceRunnerCellHtml({
        checkbox,
        number,
        runner,
        jockey,
        tipHtml: raceRunnerTipHtml(raw),
        tipKey: rawMarketId + ":" + String(selectionId),
        silkFile: raw && raw.silkFile,
        fieldSize: ordered.length,
      });
      const statusText = removed && !closed ? "REMOVED" : statusLabel;
      const bookHtml = (() => {
        const net = bookBetsSusp.length
          ? Number(runnerNetIfWins(runner, bookBetsSusp)) || 0
          : null;
        return net != null
          ? `<small class="runner-book ${net >= 0 ? "pos" : "neg"}">${formatMoney(net)}</small>`
          : "";
      })();
      return `<div class="cricket-market-row suspended race-susp-row${isWinner ? " race-winner" : ""}">
      <strong>${nameCell}${bookHtml}</strong>
      <div>${statusText}</div>
    </div>`;
    })
    .join("");
  return `<section class="cricket-market-block race-mkt">${titleHtml}${rowsHtml}</section>`;
}
