function betInfoViewer() {
  return state.role === "company" || state.role === "malik";
}
function betUplineChain(userId) {
  const out = [];
  const seen = new Set();
  const me = String(state.userId || "");
  let cur = findAccountAnywhere(userId);
  let last = null;
  while (cur && out.length < 10 && !seen.has(cur.id)) {
    seen.add(cur.id);
    last = cur;
    const you = Boolean(me) && String(cur.id) === me;
    out.push({
      name: String(cur.username || ""),
      role: cur.role === "bettor" ? "customer" : String(cur.role || ""),
      you,
    });
    if (you) return out;
    cur = cur.parentId ? findAccountAnywhere(cur.parentId) : null;
  }
  if (!out.length) return out;
  if (!(last && me && String(last.parentId || "") === me))
    out.push({ gap: true });
  out.push({
    name: String(state.username || ""),
    role: String(state.role || ""),
    you: true,
  });
  return out;
}
function betInfoFields(b) {
  if (!betInfoViewer()) return null;
  return {
    chain: betUplineChain(b.userId),
    placedAt: b.placedAt || null,
    matchedAt: b.matchedAt || null,
  };
}
const ORDERS_PAGE_SIZE = 100;
function openOrdersPopup() {
  const ev = String(state.matchEventId || "");
  if (!ev) return;
  let mid = "";
  try {
    const p = (state.cricketMatches || {})[ev] || {};
    const mk = Array.isArray(p.markets) ? p.markets : [];
    const mo =
      mk.find((m) =>
        /match.?odds/i.test(
          String((m && (m.marketType || m.marketName)) || ""),
        ),
      ) || mk[0];
    mid = String((mo && mo.marketId) || "");
  } catch (e) {}
  const url = `${routePaths.ordersPopup}?MarketId=${encodeURIComponent(mid)}&EventId=${encodeURIComponent(ev)}`;
  const w = window.open(
    url,
    `bp_orders_${ev}`,
    "width=600,height=500,scrollbars=yes,resizable=yes",
  );
  if (w) {
    try {
      w.focus();
    } catch (e) {}
  }
}
window.openOrdersPopup = openOrdersPopup;
function _ordersLoad() {
  const ctx = state.ordersCtx || {};
  if (!ctx.eventId || ctx.loading) return;
  ctx.loading = true;
  Promise.all([
    refreshBetsFromApi({ eventId: ctx.eventId, merge: true }),
    ctx.namesLoaded
      ? Promise.resolve()
      : refreshAccountsFromDb()
          .then(() => {
            ctx.namesLoaded = true;
          })
          .catch(() => {}),
  ])
    .then(() => {
      ctx.loaded = true;
    })
    .catch(() => {
      ctx.loaded = true;
      ctx.failed = true;
    })
    .finally(() => {
      ctx.loading = false;
      render();
    });
}
function ordersRefresh() {
  const ctx = state.ordersCtx || {};
  ctx.failed = false;
  _ordersLoad();
  render();
}
function ordersSort(col) {
  const ctx = state.ordersCtx || {};
  const s = ctx.sort;
  ctx.sort =
    !s || s.col !== col
      ? { col, dir: "asc" }
      : { col, dir: s.dir === "asc" ? "desc" : "asc" };
  ctx.page = 0;
  render();
}
function ordersGoPage(n) {
  const ctx = state.ordersCtx || {};
  ctx.page = Math.max(0, Number(n) || 0);
  render();
  const tb = document.querySelector(".op-tab");
  if (tb) tb.scrollIntoView({ block: "start" });
}
function _ordersRows() {
  const ev = String((state.ordersCtx || {}).eventId || "");
  const mine = (state.bets || []).filter((b) => sameEventId(b.eventId, ev));
  const row = (b) => {
    const side = String(b.side || "").toUpperCase();
    const lay =
      String(b.fancyCategory || "").toLowerCase() === "oddeven"
        ? side === "YES"
        : side === "LAY" || side === "NO";
    const bm = /bookmaker/i.test(String(b.market || b.marketType || ""));
    const r = typeof ownerClickRate === "function" ? ownerClickRate(b) : null;
    return {
      runner: `${betRunnerDisplay(b)}${bm ? " BM" : ""}`,
      price: r == null ? b.odds : `${b.odds}(${r})`,
      size: Number(b.stake) || 0,
      customer: String(b.user || ""),
      dealer: String(statementDealerName(b.userId) || ""),
      lay,
      t: Date.parse(b.placedAt || b.createdAt || "") || 0,
    };
  };
  const byNew = (a, b) => b.t - a.t;
  return {
    open: mine
      .filter((b) =>
        ["countdown", "unmatched", "open", "pending"].includes(
          String(b.status),
        ),
      )
      .map(row)
      .sort(byNew),
    matched: mine
      .filter((b) =>
        ["active", "won", "lost", "settled"].includes(String(b.status)),
      )
      .map(row)
      .sort(byNew),
  };
}
function ordersPopupView() {
  const ctx = state.ordersCtx || (state.ordersCtx = { page: 0, sort: null });
  if (!ctx.loaded && !ctx.loading) _ordersLoad();
  const spin =
    '<span class="bp-bets-spin" role="status" aria-label="Loading"></span>';
  const ready = Boolean(ctx.loaded);
  const { open, matched } = ready ? _ordersRows() : { open: [], matched: [] };
  const cell = (v) => escapeHtml(String(v == null ? "" : v));
  const openRows = open
    .map(
      (r) =>
        `<tr class="${r.lay ? "op-l" : "op-b"}"><td>${cell(r.runner)}</td><td>${cell(r.price)}</td><td>${cell(formatMoney(r.size))}</td><td>${cell(r.customer)}</td><td>${cell(r.dealer)}</td></tr>`,
    )
    .join("");
  const cols = [
    ["runner", "Runner"],
    ["price", "Price"],
    ["size", "Size"],
    ["customer", "Customer"],
    ["dealer", "Dealer"],
  ];
  let list = matched;
  if (ctx.sort) {
    const { col, dir } = ctx.sort;
    const num2 = (v) => {
      const n = Number(String(v).replace(/[^0-9.-]/g, ""));
      return Number.isFinite(n) ? n : NaN;
    };
    list = [...matched].sort((a, b) => {
      const an = num2(a[col]),
        bn = num2(b[col]);
      const c =
        (col === "price" || col === "size") &&
        Number.isFinite(an) &&
        Number.isFinite(bn)
          ? an - bn
          : String(a[col]).localeCompare(String(b[col]));
      return dir === "asc" ? c : -c;
    });
  }
  const pages = Math.max(1, Math.ceil(list.length / ORDERS_PAGE_SIZE));
  const page = Math.min(ctx.page || 0, pages - 1);
  const slice = list.slice(
    page * ORDERS_PAGE_SIZE,
    (page + 1) * ORDERS_PAGE_SIZE,
  );
  const head = cols
    .map(([k, label]) => {
      const st = ctx.sort && ctx.sort.col === k ? ctx.sort.dir : "none";
      return `<div class="op-col" role="columnheader" aria-sort="${st === "asc" ? "ascending" : st === "desc" ? "descending" : "none"}" onclick="ordersSort('${k}')"><span class="op-col-title">${label}</span><span class="op-arrow"></span></div>`;
    })
    .join("");
  const body = slice
    .map(
      (r) =>
        `<div class="op-row ${r.lay ? "op-l" : "op-b"}" role="row"><div class="op-cell">${cell(r.runner)}</div><div class="op-cell">${cell(r.price)}</div><div class="op-cell">${cell(formatMoney(r.size))}</div><div class="op-cell">${cell(r.customer)}</div><div class="op-cell">${cell(r.dealer)}</div></div>`,
    )
    .join("");
  const from = list.length ? page * ORDERS_PAGE_SIZE + 1 : 0,
    to = Math.min(list.length, (page + 1) * ORDERS_PAGE_SIZE);
  const lo = Math.max(0, Math.min(page - 2, pages - 5)),
    hi = Math.min(pages, lo + 5);
  const btn = (label, n, dis, act) =>
    `<button type="button" class="op-page${act ? " active" : ""}" ${dis ? "disabled" : `onclick="ordersGoPage(${n})"`}>${label}</button>`;
  const pager =
    btn("First", 0, page === 0) +
    btn("Prev", page - 1, page === 0) +
    Array.from({ length: hi - lo }, (_, i) =>
      btn(String(lo + i + 1), lo + i, false, lo + i === page),
    ).join("") +
    btn("Next", page + 1, page >= pages - 1) +
    btn("Last", pages - 1, page >= pages - 1);
  return `<main class="orders-pop"><div class="op-card"><div class="op-body">
    <h5>UnMatched (${ready ? open.length : spin}) <button type="button" class="op-refresh" onclick="ordersRefresh()">Refresh</button></h5>
    <table class="op-table"><thead><tr><th>Runner</th><th>Price</th><th>Size</th><th>Customer</th><th>Dealer</th></tr></thead><tbody>${openRows}</tbody></table>
    <h5>Matched (${ready ? matched.length : spin})</h5>
    <div class="op-tab" role="grid">
      <div class="op-tab-head" role="row">${head}</div>
      <div class="op-tab-body">${body}</div>
      <div class="op-tab-foot"><span class="op-counter">Showing ${from}-${to} of ${list.length} rows</span><span class="op-pager">${pager}</span></div>
    </div>
  </div></div></main>`;
}
