function cricketScoreCardForProfile(profile, teams) {
  const score = profile.score || {};
  const data = cricketMultiDayView(
    score.data || {},
    String(state.matchEventId || ""),
  );
  const num2 = (v) => (v == null || v === "" ? "" : String(v).trim());
  const scoreTeams = Array.isArray(data.teams) ? data.teams : [];
  const t1 = scoreTeams[0] || {};
  const t2 = scoreTeams[1] || {};
  const cleanName = (n) => num2(n).replace(/\s+W$/i, "");
  const name1 =
    cleanName(t1.team_name || t1.team_short_name) ||
    cleanName(teams[0]) ||
    "Team A";
  const name2 =
    cleanName(t2.team_name || t2.team_short_name) ||
    cleanName(teams[1]) ||
    "Team B";
  const fixScore = (s) => num2(s).replace(/(\d)\s*-\s*(\d)/, "$1/$2");
  const innScore = (t) =>
    data._multiDay && Array.isArray(t._innings)
      ? t._innings
          .filter((s, i) => i === 0 || /[1-9]/.test(s))
          .map(fixScore)
          .join(" & ")
      : fixScore(t.score);
  const score1 = innScore(t1);
  const score2 = innScore(t2);
  const over = num2(data.current_over).replace(/[()]/g, "");
  const totalOvers = num2(data.total_over) || num2(data.total_overs) || "20";
  const inning =
    scoreTeams.filter((t) => num2(t.score)).length >= 2 ? "2" : "1";
  const message =
    num2(data.msg) ||
    num2(data.status_message) ||
    num2(score.description) ||
    "";
  const mainScore = [score1, score2].filter(Boolean).join(" : ");
  if (!mainScore && !message) return "";
  const topLabel = over
    ? data._multiDay
      ? `${over} OV`
      : `INN ${inning} | ${over}/${totalOvers} OV`
    : "";
  return `<div class="cricket-score-card">
    <div class="score-top"><strong>${escapeHtml(name1)}</strong><span>${escapeHtml(topLabel)}</span><strong>${escapeHtml(name2)}</strong></div>
    ${mainScore ? `<div class="score-main"><b>${escapeHtml(mainScore)}</b></div>` : ""}
    ${message ? `<p>${escapeHtml(message)}</p>` : ""}
  </div>`;
}
