const bpAkSnd = {
  cache: {},
  queue: [],
  playing: false,
  lastBanner: "",
  lastBalls: null,
  warned: {},
  preloaded: false,
};
function bpAkSndPreload() {
  if (bpAkSnd.preloaded) return;
  bpAkSnd.preloaded = true;
  for (const n of BP_AK_SND_ALL) {
    try {
      const a = new Audio(BP_AK_SND_BASE + n + ".mp3");
      a.preload = "auto";
      bpAkSnd.cache[n] = a;
    } catch (e) {}
  }
}
function bpAkSndPump() {
  if (bpAkSnd.playing) return;
  const name = bpAkSnd.queue.shift();
  if (!name) return;
  const base = bpAkSnd.cache[name];
  if (!base) {
    bpAkSndPump();
    return;
  }
  const el = base.paused ? base : base.cloneNode(true);
  bpAkSnd.playing = true;
  let done = false;
  const next = () => {
    if (done) return;
    done = true;
    bpAkSnd.playing = false;
    bpAkSndPump();
  };
  el.onended = next;
  const durMs =
    Number.isFinite(el.duration) && el.duration > 0 ? el.duration * 1e3 : 4e3;
  setTimeout(next, durMs + 300);
  el.volume = 1;
  try {
    el.currentTime = 0;
  } catch (e) {}
  el.play().catch(next);
}
function bpAkSndEnqueue(name) {
  if (!name || !bpAkSnd.cache[name]) return;
  if (bpAkSnd.queue.length >= 3) bpAkSnd.queue.shift();
  bpAkSnd.queue.push(name);
  bpAkSndPump();
}
