async function refreshMyRequests() {
  try {
    const d = await getJson("/api/db/money-requests");
    state.myRequests = {
      deposits: d.deposits || [],
      withdrawals: d.withdrawals || [],
    };
  } catch {
    state.myRequests = { deposits: [], withdrawals: [] };
  }
  render();
}
function myRequestsSection() {
  const mr = state.myRequests || { deposits: [], withdrawals: [] };
  const rows = [
    ...(mr.deposits || []).map((r) => ({ ...r, kind: "Deposit" })),
    ...(mr.withdrawals || []).map((r) => ({ ...r, kind: "Withdraw" })),
  ].sort((a, b) =>
    String(b.createdAt || "").localeCompare(String(a.createdAt || "")),
  );
  if (!rows.length) return "";
  const badge = (s) => {
    const cls = s === "completed" ? "mp-pos" : s === "rejected" ? "mp-neg" : "";
    return `<span class="${cls}">${escapeHtml(titleCase(s || "pending"))}</span>`;
  };
  return `<section class="market-position-page" style="margin-top:10px">
    <div class="mp-head"><span class="mp-title">My Requests</span><button class="mp-refresh" type="button" onclick="refreshMyRequests()">${escapeHtml(T("Refresh"))}</button></div>
    <table class="market-position-table"><thead><tr><th>${escapeHtml(T("col:Type"))}</th><th>${escapeHtml(T("col:Detail"))}</th><th class="mp-amount-col">${escapeHtml(T("col:Amount"))}</th><th>${escapeHtml(T("col:Status"))}</th></tr></thead>
      <tbody>${rows
        .slice(0, 30)
        .map(
          (r) => `<tr>
        <td>${r.kind}</td>
        <td>${escapeHtml((r.depositAccount && r.depositAccount.label) || (r.savedAccount && r.savedAccount.label) || r.bank || r.transactionId || "-")}${r.proofFile ? ` \xB7 <a href="/api/deposit-proof/${encodeURIComponent(r.id)}" target="_blank" rel="noopener">proof</a>` : ""}</td>
        <td class="mp-amount-col">${formatMoney(Number(r.amount) || 0)}</td>
        <td>${badge(r.status)}</td>
      </tr>`,
        )
        .join("")}</tbody>
    </table>
  </section>`;
}
