function compressImage(file, maxDim, quality) {
  return new Promise((resolve, reject) => {
    const url = URL.createObjectURL(file);
    const img = new Image();
    img.onload = () => {
      URL.revokeObjectURL(url);
      let w = img.naturalWidth || img.width,
        h = img.naturalHeight || img.height;
      if (Math.max(w, h) > maxDim) {
        const s = maxDim / Math.max(w, h);
        w = Math.round(w * s);
        h = Math.round(h * s);
      }
      const canvas = document.createElement("canvas");
      canvas.width = w;
      canvas.height = h;
      canvas.getContext("2d").drawImage(img, 0, 0, w, h);
      try {
        resolve(canvas.toDataURL("image/jpeg", quality));
      } catch (e) {
        reject(e);
      }
    };
    img.onerror = () => {
      URL.revokeObjectURL(url);
      reject(new Error("image load failed"));
    };
    img.src = url;
  });
}
async function onProofPick(input) {
  const f = input.files && input.files[0];
  if (!f) {
    state.proofData = null;
    return;
  }
  if (!/^image\//.test(f.type || "")) {
    flash("Sirf screenshot/image chalega");
    input.value = "";
    return;
  }
  if (f.size > 15 * 1024 * 1024) {
    flash("Screenshot bahut bari \u2014 15MB se choti");
    input.value = "";
    return;
  }
  try {
    state.proofData = await compressImage(f, 1400, 0.7);
    flash("Screenshot lag gaya");
  } catch {
    await new Promise((done) => {
      const r = new FileReader();
      r.onload = () => {
        state.proofData = String(r.result || "");
        done();
      };
      r.onerror = done;
      r.readAsDataURL(f);
    });
    if (state.proofData) flash("Screenshot lag gaya");
  }
  render();
}
function toggleSavedAdd() {
  state.savedAdd = !state.savedAdd;
  render();
}
async function submitSavedAccount(trigger) {
  const box =
    (trigger && trigger.closest && trigger.closest(".bp-saved-add")) ||
    document;
  const val = (n) => {
    const el = box.querySelector(`[name="${n}"]`);
    return el ? String(el.value || "") : "";
  };
  const payload = {
    label: val("label"),
    accType: val("accType"),
    holder: val("holder"),
    accountNumber: val("accountNumber"),
    iban: val("iban"),
    bank: val("bank"),
  };
  if ((state.savedAccounts || []).length >= 5)
    return flash("Maximum 5 accounts allowed");
  if (payload.accType === "custom" && !payload.label.trim())
    return flash("Enter account type name");
  if (payload.accType === "crypto") {
    if (!payload.bank.trim()) return flash("Coin select karein");
    if (!payload.accountNumber.trim()) return flash("Wallet address required");
  } else {
    if (!payload.holder.trim()) return flash("Enter account name");
    if (!payload.accountNumber.trim()) return flash("Enter account number");
    if (payload.accType === "bank" && !payload.bank.trim())
      return flash("Select bank");
  }
  if (!payload.label.trim())
    payload.label =
      payload.accType === "crypto"
        ? payload.bank
        : acctTypeLabel(payload.accType);
  try {
    const r = await postJson("/api/db/saved-accounts", payload);
    state.savedAdd = false;
    state.moneyPickId = r.account ? r.account.id : "";
    await refreshSavedAccounts();
    flash("Account save ho gaya");
    render();
  } catch (error) {
    flash(feedMsg ? feedMsg(error, "Save failed") : error.message);
  }
}
async function deleteSavedAccount(id) {
  try {
    await delJson(`/api/db/saved-accounts/${encodeURIComponent(id)}`);
    await refreshSavedAccounts();
  } catch (error) {
    flash(error.message);
  }
}
async function submitMoneyRequest(event) {
  event.preventDefault();
  if (state._moneyBusy) return;
  const type = state.moneyModal;
  const fd = new FormData(event.currentTarget);
  const amount = Math.max(0, Number(fd.get("amount")) || 0);
  let payload;
  if (type === "deposit") {
    {
      const lo = curLimit("depositMin", 100),
        hi = curLimit("depositMax", 5e6);
      if (amount < lo)
        return flash(
          `${T("Minimum deposit is")} ${curLabel()} ${formatMoney(toMinor(lo))}`,
        );
      if (amount > hi)
        return flash(
          `${T("Maximum deposit is")} ${curLabel()} ${formatMoney(toMinor(hi))}`,
        );
    }
    if (!String(fd.get("txn") || "").trim())
      return flash("Enter Transaction ID / Reference Number");
    if (!state.proofData) return flash("Payment screenshot is required");
    payload = {
      type: "deposit",
      ref: "",
      amount,
      transactionId: String(fd.get("txn") || "").trim(),
      depositAccountId: state.moneyPickId || "",
      proof: state.proofData || "",
    };
  } else {
    {
      const lo = curLimit("withdrawMin", 500),
        hi = curLimit("withdrawMax", 2e5);
      if (amount < lo)
        return flash(
          `${T("Minimum withdrawal is")} ${curLabel()} ${formatMoney(toMinor(lo))}`,
        );
      if (amount > hi)
        return flash(
          `${T("Maximum")} ${curLabel()} ${formatMoney(toMinor(hi))} ${T("per transaction")}`,
        );
    }
    if (!state.moneyPickId) return flash("Please select a payment account");
    payload = {
      type: "withdrawal",
      amount,
      savedAccountId: state.moneyPickId,
      nonce: `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`,
    };
  }
  state._moneyBusy = true;
  const btn = event.currentTarget.querySelector('button[type="submit"]');
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Bhej rahe\u2026";
  }
  try {
    await postJson("/api/db/money-requests", payload);
    state.moneyModal = null;
    state.proofData = null;
    state._moneyBusy = false;
    afterSaveReload(
      type === "deposit"
        ? "Kindly wait, system will check your money and deposit shortly. Expected time: 5 minutes"
        : "Kindly wait, your payment will be in your account in no time",
    );
  } catch (error) {
    state._moneyBusy = false;
    if (btn) {
      btn.disabled = false;
      btn.textContent = "Submit Request";
    }
    flash(feedMsg ? feedMsg(error, "Request failed") : error.message);
  }
}
function acctTypeLabel(t) {
  return BPPaymentMethods.shortLabel(t);
}
function accountLine(a) {
  const bits = [
    a.bank && `${escapeHtml(a.bank)}`,
    a.accountNumber && `A/C ${escapeHtml(a.accountNumber)}`,
    a.iban && `IBAN ${escapeHtml(a.iban)}`,
    a.holder && `(${escapeHtml(a.holder)})`,
  ]
    .filter(Boolean)
    .join(" \xB7 ");
  return bits || "\u2014";
}
