const BD_SORT_DEFAULT = { col: "name", dir: "asc" };
function bdSortTh(label, col) {
  const st = state.bdSort || BD_SORT_DEFAULT;
  const dir = st.col === col ? st.dir : "";
  return `<th class="ledger-th${dir ? " dt-" + dir : ""}" onclick="sortBookDetail('${col}')"><span class="dt-col-title">${label}</span><span class="dt-col-order"></span></th>`;
}
function sortBookDetail(col) {
  const st = state.bdSort || BD_SORT_DEFAULT;
  if (st.col !== col) state.bdSort = { col, dir: "asc" };
  else if (st.dir === "asc") state.bdSort = { col, dir: "desc" };
  else state.bdSort = { col: null, dir: "" };
  render();
}
function toggleBookDetailHideZero(on) {
  state.bdHideZero = Boolean(on);
  render();
}
function balanceView() {
  ensureReportData("bookDetail");
  const bdData = state.reportData && state.reportData.bookDetail;
  const bdRows = bdData ? bdData.rows : [];
  const leftRows = bdRows.filter((r) => (Number(r.amount) || 0) >= 0);
  const rightRows = bdRows.filter((r) => (Number(r.amount) || 0) < 0);
  const bdOwnerName =
    typeof operatorScopeAccount === "function" && operatorScopeAccount()
      ? operatorScopeAccount().username || state.username
      : state.username;
  registerReportExport(
    `${bdOwnerName} - Book Detail`,
    bdRows.map((r) => [r.name, Number(r.amount) || 0]),
  );
  const nameCell = (r) =>
    r.self
      ? `<span>${escapeHtml(r.name)}</span>`
      : `<a class="bookdetail-link" href="#" onclick='openBookDetailChild(${JSON.stringify(r.name)});return false;'>${escapeHtml(r.name)}</a>`;
  const sortRows = (list) => {
    const st = state.bdSort || BD_SORT_DEFAULT;
    if (!st.col) return list;
    const mul = st.dir === "desc" ? -1 : 1;
    return list
      .slice()
      .sort((a, b) =>
        st.col === "amount"
          ? ((Number(a.amount) || 0) - (Number(b.amount) || 0)) * mul
          : String(a.name).localeCompare(String(b.name), void 0, {
              sensitivity: "base",
            }) * mul,
      );
  };
  const hideZero = state.bdHideZero === true;
  const prep = (list) =>
    sortRows(
      hideZero ? list.filter((r) => (Number(r.amount) || 0) !== 0) : list,
    );
  const pairCol = (list, totalClass) => {
    const rows = prep(list);
    const total = rows.reduce((sum, row) => sum + (Number(row.amount) || 0), 0);
    return `<div class="bd-col">
      <table class="table table-bordered report-mini-table"><thead><tr>${bdSortTh(T("col:Name"), "name")}${bdSortTh(T("col:Amount"), "amount")}</tr></thead><tbody>${rows.length ? rows.map((r) => `<tr class="${r.self ? "report-self-row" : ""}"><td>${nameCell(r)}</td><td class="${r.amount < 0 ? "position-minus" : "position-plus"}">${money(r.amount)}</td></tr>`).join("") : reportEmptyRow(2)}</tbody></table>
      <table class="table bd-total-band"><tbody><tr class="${totalClass}"><th>${escapeHtml(T("col:Total"))}</th><th>${money(total)}</th></tr></tbody></table>
    </div>`;
  };
  const mainCard = `<section class="card report-result-card bd-card">
    <div class="plain-card-header bd-head">
      <div class="bd-head-title">&#9776; <strong>${escapeHtml(state.username)}</strong></div>
      <label class="hide-zero"><input type="checkbox" ${hideZero ? "checked" : ""} onchange="toggleBookDetailHideZero(this.checked)"> ${escapeHtml(T("Hide Zero Amounts"))}</label>
      <div class="bd-head-dash">-</div>
    </div>
    <div class="card-body report-pair-body">${pairCol(leftRows, "total-green")}${pairCol(rightRows, "total-red")}</div>
  </section>`;
  let eventsCard = "";
  if (state.bookDetailChild) {
    const extra = `&child=${encodeURIComponent(state.bookDetailChild)}`;
    ensureReportData(
      "bookDetailEvents",
      extra,
      `bdEvents:${state.bookDetailChild}`,
    );
    const evRows = serverReportRows(`bdEvents:${state.bookDetailChild}`);
    const evTotal = evRows.reduce((sum, row) => sum + row[1], 0);
    eventsCard = `<section class="card report-result-card">
      <div class="plain-card-header">&#9776; <strong>${escapeHtml(state.bookDetailChild)}</strong></div>
      <div class="card-body"><table class="table table-bordered report-single-table"><thead><tr><th>${escapeHtml(T("col:Event"))}</th><th>${escapeHtml(T("col:Amount"))}</th></tr></thead><tbody>
      ${evRows.length ? evRows.map(([sport, amount]) => `<tr><td><a class="bookdetail-link" href="#" onclick='openBookDetailSport(${JSON.stringify(sport)});return false;'>${escapeHtml(sport)}</a></td><td class="${amount < 0 ? "position-minus" : "position-plus"}">${money(amount)}</td></tr>`).join("") : reportEmptyRow(2)}
      <tr class="${evTotal < 0 ? "total-red" : "total-green"}"><th>${escapeHtml(T("col:Total"))}</th><th>${money(evTotal)}</th></tr></tbody></table></div>
    </section>`;
  }
  let detailCard = "";
  if (state.bookDetailChild && state.bookDetailSport) {
    const extra = `&child=${encodeURIComponent(state.bookDetailChild)}&event=${encodeURIComponent(state.bookDetailSport)}`;
    const key = `bdDetail:${state.bookDetailChild}:${state.bookDetailSport}`;
    ensureReportData("bookDetailEventDetail", extra, key);
    const data = state.reportData && state.reportData[key];
    const dRows = data ? data.rows : [];
    const dTotal = dRows.reduce(
      (sum, row) => sum + (Number(row.amount) || 0),
      0,
    );
    detailCard = dateEventReportCard(
      `${escapeHtml(state.bookDetailChild)} / ${escapeHtml(state.bookDetailSport)}`,
      dRows,
      dTotal,
    );
  }
  const drill =
    eventsCard || detailCard
      ? `<div class="bookdetail-drill">${eventsCard}${detailCard}</div>`
      : "";
  return dealerShell(
    "Reports",
    `${reportTypePanel()}${reportDateFilter()}<div class="bookdetail-grid">${mainCard}${drill}</div>`,
  );
}
function reportRangeDefaults() {
  const now = new Date();
  const pad = (n) => String(n).padStart(2, "0");
  const d = (x) =>
    `${x.getFullYear()}-${pad(x.getMonth() + 1)}-${pad(x.getDate())}`;
  if (!state.reportFrom) state.reportFrom = `${d(now)}T00:00`;
  if (!state.reportTo) state.reportTo = `${d(now)}T23:59`;
}
function setReportRange(which, value) {
  const day = String(value || "").slice(0, 10);
  if (!day) return;
  if (which === "from") state.reportFrom = `${day}T00:00`;
  else state.reportTo = `${day}T23:59`;
}
function reportRangeMsFrom() {
  const t = Date.parse(state.reportFrom || "");
  return Number.isFinite(t) ? t : "";
}
function reportRangeMsTo() {
  const t = Date.parse(state.reportTo || "");
  return Number.isFinite(t) ? t + 59999 : "";
}
const REPORT_TYPE_BY_PAGE = {
  balance: "bookDetail",
  dailyPl: "dailyPl",
  dailyReport: "daily",
  bookDetail2: "bookDetail2",
  commissionReport: "commission",
  manualCommissionReport: "commission",
};
async function refreshReportFromApi(type, extra = "", key = type) {
  reportRangeDefaults();
  const fromMs = Date.parse(state.reportFrom);
  const toMs = Date.parse(state.reportTo);
  const qs = `type=${encodeURIComponent(type)}&from=${encodeURIComponent(Number.isFinite(fromMs) ? fromMs : state.reportFrom)}&to=${encodeURIComponent(Number.isFinite(toMs) ? toMs + 59999 : state.reportTo)}${extra}`;
  const data = await getJson(`/api/admin/reports?${qs}`);
  state.reportData = state.reportData || {};
  state.reportData[key] = {
    rows: data.rows || [],
    total: Number(data.total) || 0,
    leaf: data.leaf === true,
    account: data.account || "",
    range: `${state.reportFrom}|${state.reportTo}${extra}`,
    fetchedAt: Date.now(),
  };
  return state.reportData[key];
}
function ensureReportData(type, extra = "", key = type) {
  reportRangeDefaults();
  const cur = state.reportData && state.reportData[key];
  const range = `${state.reportFrom}|${state.reportTo}${extra}`;
  if (cur && cur.range === range && Date.now() - cur.fetchedAt < 15e3) return;
  if (state._reportLoading === `${key}|${range}`) return;
  state._reportLoading = `${key}|${range}`;
  refreshReportFromApi(type, extra, key)
    .then(() => {
      state._reportLoading = "";
      state._reportTries = 0;
      render();
    })
    .catch(() => {
      state._reportLoading = "";
      state._reportTries = (state._reportTries || 0) + 1;
      if (state._reportTries <= 8)
        setTimeout(() => {
          if (state.authed) render();
        }, 1500);
    });
}
function submitReportFilter() {
  const type = REPORT_TYPE_BY_PAGE[state.page];
  if (!type) {
    render();
    return;
  }
  if (state.page === "manualCommissionReport") {
    state.mcommPath = [];
    render();
    return;
  }
  if (type === "bookDetail") {
    state.bookDetailChild = "";
    state.bookDetailSport = "";
  }
  if (type === "bookDetail2") {
    state.bd2Sport = "";
    state.bd2Child = "";
  }
  if (type === "dailyPl" || type === "daily") {
    state.dpChild = "";
    state.dpSport = "";
  }
  if (type === "commission") state.commPath = [];
  refreshReportFromApi(type)
    .then(render)
    .catch((e) => flash(feedMsg(e, "Report load failed")));
}
