function finalSheetView() {
  const path = Array.isArray(state.fsPath) ? state.fsPath : [];
  const cur = path.length
    ? path[path.length - 1]
    : { id: "", name: state.username || "" };
  const loadKey = `fs:${cur.id}`;
  const have = cur.id ? (state.fsSheets || {})[cur.id] : state.balanceSheet;
  const fsFresh =
    state._fsFetchAt &&
    state._fsFetchAt[loadKey] &&
    Date.now() - state._fsFetchAt[loadKey] < 15e3;
  if ((!have || !fsFresh) && state._fsLoading !== loadKey) {
    state._fsLoading = loadKey;
    refreshBalanceSheetFromApi(cur.id || void 0)
      .then(() => {
        state._fsLoading = "";
        state._fsTries = 0;
        (state._fsFetchAt = state._fsFetchAt || {})[loadKey] = Date.now();
        render();
      })
      .catch(() => {
        state._fsLoading = "";
        state._fsTries = (state._fsTries || 0) + 1;
        if (state._fsTries <= 5)
          setTimeout(() => {
            if (state.page === "finalSheet") render();
          }, 1500);
      });
  }
  const sheet = have;
  const hideZero = state.fsHideZero !== false;
  const mapRow = (row, sign) => {
    const label =
      row.label === "Book Account"
        ? cur.name
        : row.label === "Cash Account"
          ? "Cash"
          : row.label;
    return [
      label,
      sign * (Number(row.amount) || 0),
      row.label === "Book Account",
      row,
    ];
  };
  const FS_HIDDEN = new Set([
    "balance_check",
    "credit_given",
    "credit_received",
    "commission",
    "manual_commission",
    "commission_source",
  ]);
  let left = (sheet?.plus || [])
    .filter((r) => !FS_HIDDEN.has(r.source))
    .map((r) => mapRow(r, 1));
  let right = (sheet?.minus || [])
    .filter((r) => !FS_HIDDEN.has(r.source))
    .map((r) => mapRow(r, -1));
  if (hideZero) {
    left = left.filter((r) => r[1] !== 0);
    right = right.filter((r) => r[1] !== 0);
  }
  registerReportExport(
    `${cur.name} - Final Sheet`,
    [...left, ...right].filter(([n]) => n !== "-").map(([n, a]) => [n, a]),
  );
  const fsNameCell = (name, row) => {
    const isDealerChild =
      row &&
      row.source === "child" &&
      String(row.role || "") !== "bettor" &&
      row.ownerId;
    return isDealerChild
      ? `<a class="bookdetail-link" href="#" onclick="${attrJs(`openDealerScope(${JSON.stringify(String(row.ownerId))})`)}">${escapeHtml(name)}</a>`
      : row && row.source === "cash"
        ? `<span class="fs-cash">${escapeHtml(name)}</span>`
        : escapeHtml(name);
  };
  const pairTable = (list, totalClass, side, otherLen) => {
    const t = list.reduce((sum, row) => sum + row[1], 0);
    const amountClass = side === "right" ? "position-minus" : "position-plus";
    return `<table class="table table-bordered report-mini-table"><thead><tr><th>${escapeHtml(T("col:Name"))}</th><th>${escapeHtml(T("col:Amount"))}</th></tr></thead><tbody>${list.length ? list.map(([name, amount, , row]) => `<tr><td class="position-plus">${fsNameCell(name, row)}</td><td class="${amountClass}">${side === "right" ? "-" : ""}${money(Math.abs(amount))}</td></tr>`).join("") : reportEmptyRow(2)}${reportPadRows(list.length || 1, otherLen || 1)}<tr class="${totalClass}"><th>${escapeHtml(T("col:Total"))}</th><th>${side === "right" ? "-" : ""}${money(Math.abs(t))}</th></tr></tbody></table>`;
  };
  const crumbs = [{ id: "", name: state.username || "" }, ...path];
  const crumbHtml = crumbs
    .map((c, i) =>
      i === crumbs.length - 1
        ? `<span class="comm-crumb-cur">${escapeHtml(c.name)}</span>`
        : `<a class="bookdetail-link" href="#" onclick="${attrJs(`setFinalSheetPath(${JSON.stringify(path.slice(0, i))})`)}">${escapeHtml(c.name)}</a>`,
    )
    .join(`<span class="comm-crumb-sep">&rsaquo;</span>`);
  const body = `<section class="card report-result-card">
    <div class="plain-card-header">&#9776; <strong>${escapeHtml(TX("{x} - Final Sheet", cur.name))}</strong>${path.length ? `<span class="comm-crumbs">${crumbHtml}</span>` : ""}<label class="hide-zero"><input type="checkbox" ${hideZero ? "checked" : ""} onchange="toggleFsHideZero()"> Hide Zero Amounts</label></div>
    <div class="card-body report-pair-body">${reportExportButtons()}${pairTable(left, "total-green", "left", right.length)}${pairTable(right, "total-red", "right", left.length)}</div>
  </section>`;
  return dealerShell("Reports", `${reportTypePanel()}${body}`);
}
