function viewerGapFraction(betUserId, accountsById, viewerId, viewerShare) {
  if (typeof BPPosition !== "undefined")
    return BPPosition.viewerGapFraction(
      betUserId,
      accountsById,
      viewerId,
      viewerShare,
    );
  let node = accountsById.get(String(betUserId));
  let guard = 0;
  while (node && String(node.parentId) !== String(viewerId) && guard++ < 20) {
    node = accountsById.get(String(node.parentId));
  }
  const childShare = node ? Number(node.share ?? node.share_percent) || 0 : 0;
  return Math.max(0, viewerShare - childShare) / 100;
}
