async function forceSettleNow(btn) {
  if (state._forceSettling) return;
  state._forceSettling = true;
  if (btn) {
    btn.disabled = true;
    btn.textContent = "Settling\u2026";
  }
  try {
    const r = await postJson("/api/admin/force-settle", {});
    const remaining = (r.events || []).filter((e) => e.after > 0);
    const held = (r.events || []).reduce(
      (s, e) => s + (Number(e.reviewHeld) || 0),
      0,
    );
    const names = remaining
      .map((e) => e.title)
      .slice(0, 3)
      .join(", ");
    flash(
      `Force settle: ${r.settled} bets settle hue${remaining.length ? ` \u2014 ${remaining.length} event(s) baqi (${names}${remaining.length > 3 ? "\u2026" : ""})` : " \u2014 sab saaf"}${held ? ` \u2014 \u26A0 ${held} bet REVIEW-HOLD par hain (release karen, phir settle hongi)` : ""}`,
    );
    await refreshBetsFromApi().catch(() => {});
    await refreshAccountsFromDb().catch(() => {});
  } catch (error) {
    flash(error.message || "Force settle failed");
  }
  state._forceSettling = false;
  render();
}
