async function approveRequest(type, id, approve) {
  const list = state.requests[type];
  const req = list.find((item) => item.id === id);
  if (!req || req.status !== "pending") return;
  try {
    await postJson(`/api/db/money-requests/${encodeURIComponent(id)}`, {
      action: approve ? "approve" : "reject",
    });
    req.status = approve ? "completed" : "rejected";
    await refreshMoneyRequestsFromDb();
    await refreshAccountsFromDb();
  } catch (error) {
    flash(error.message);
    return;
  }
  persist();
  flash(`${type} request ${req.status}`);
  render();
}
