function requestTable(type) {
  const rows = state.requests[type] || [];
  const isDep = type === "deposits";
  const detail = (req) => {
    if (isDep) {
      const acc = req.depositAccount
        ? `<strong>${escapeHtml(req.depositAccount.label)}</strong>`
        : "";
      const txn = req.transactionId
        ? `Txn ${escapeHtml(req.transactionId)}`
        : "";
      const proof = req.proofFile
        ? `<a href="/api/deposit-proof/${encodeURIComponent(req.id)}" target="_blank" rel="noopener">proof</a>`
        : "";
      return (
        [acc, txn, proof].filter(Boolean).join(" \xB7 ") ||
        escapeHtml(req.ref || "")
      );
    }
    const base = req.savedAccount
      ? accountLine(req.savedAccount)
      : escapeHtml(req.bank || "");
    const flags =
      Array.isArray(req.flags) && req.flags.length
        ? `<div class="mp-neg" style="margin-top:4px;font-size:12px">\u26A0 ${req.flags.map((f) => escapeHtml(f.msg || f.code || "")).join(" \xB7 ")}</div>`
        : "";
    return base + flags;
  };
  return `<div class="table-scroll"><table class="highlight-table"><thead><tr><th>User</th><th>${escapeHtml(T("col:Amount"))}</th><th>Detail / Account</th><th>Status</th><th>Action</th></tr></thead><tbody>${rows.map((req) => `<tr><td>${escapeHtml(req.user || "")}</td><td>${rs(req.amount)}</td><td>${detail(req)}</td><td>${escapeHtml(req.status || "")}</td><td style="white-space:nowrap">${req.status === "pending" ? `<button class="green-btn" onclick="approveRequest('${type}','${req.id}',true)">Approve</button><button class="green-btn danger-lite" onclick="approveRequest('${type}','${req.id}',false)">Reject</button>` : "\u2014"}</td></tr>`).join("")}</tbody></table></div>`;
}
