function pktTime(iso) {
  if (!iso) return "";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return escapeHtml(String(iso));
  return new Date(d.getTime() + 5 * 3600 * 1e3)
    .toISOString()
    .replace("T", " ")
    .slice(0, 19);
}
