function ladderText(l) {
  if (!l) return "";
  if (l.matched_odds !== void 0)
    return `MARKER matched ${l.matched_odds} ${l.side} stake ${l.stake}`;
  if (l.odds)
    return Object.entries(l.odds)
      .map(([k, v]) => `${k}: ${v.back}/${v.lay}`)
      .join("  \xB7  ");
  return JSON.stringify(l);
}
