async function submitPaymentAccount(event) {
  event.preventDefault();
  const form = event.currentTarget;
  const fd = new FormData(form);
  const accType = String(fd.get("accType") || "bank");
  const bank = String(fd.get("bank") || "").trim();
  const label =
    (accType === "bank" ? bank : "") ||
    BPPaymentMethods.shortLabel(accType) ||
    "Account";
  const payload = {
    label,
    accType,
    holder: fd.get("holder"),
    accountNumber: fd.get("accountNumber"),
    iban: fd.get("iban"),
    bank,
  };
  try {
    await postJson("/api/db/payment-accounts", payload);
    form.reset();
    await refreshPaymentAccounts();
    flash("Account add ho gaya");
  } catch (error) {
    flash(feedMsg ? feedMsg(error, "Add failed") : error.message);
  }
}
function paTypeChanged(sel) {
  const form = sel && sel.form;
  if (!form) return;
  const isBank = String(sel.value || "") === "bank";
  form.querySelectorAll(".pa-bank").forEach((el) => {
    el.hidden = !isBank;
    const inp = el.querySelector("input");
    if (!inp) return;
    if (inp.name === "bank") inp.required = isBank;
    if (!isBank) inp.value = "";
  });
}
