async function saveExchangeControl(eventId, i) {
  if (!state._ecLoaded)
    return flash(
      "Exchange-controls load nahi hui \u2014 save band. Refresh karein.",
    );
  const num2 = (id) => {
    const el = document.getElementById(id);
    return el ? el.value : "";
  };
  const maxBet = Math.max(0, Math.floor(Number(num2(`ec-maxbet-${i}`)) || 0));
  const maxWin = Math.max(0, Math.floor(Number(num2(`ec-maxwin-${i}`)) || 0));
  const delay = Math.max(
    0,
    Math.min(60, Math.floor(Number(num2(`ec-delay-${i}`)) || 0)),
  );
  try {
    await postJson("/api/admin/match-limit", { eventId, maxBet, maxWin });
    await postJson("/api/admin/match-delay", { eventId, delay });
    state.exchangeControls = state.exchangeControls || {
      limits: {},
      delays: {},
    };
    state.exchangeControls.limits[eventId] = { maxBet, maxWin };
    state.exchangeControls.delays[eventId] = delay;
    flash("Exchange control saved");
  } catch (e) {
    flash(feedMsg(e, "Save failed"));
  }
}
