function owPickDealer(id) {
  owState().dealerId = id;
  state._owLoaded = false;
  state._owLoading = false;
  refreshOneWindow();
}
function owPreview(input, type) {
  const form = input.closest("form");
  if (!form) return;
  const cid = (form.querySelector('[name="customerId"]') || {}).value || "";
  const amt = Number((form.querySelector('[name="amount"]') || {}).value) || 0;
  const c = (owState().customers || []).find((x) => x.id === cid);
  const badge = document.getElementById("ow-badge-" + type);
  if (!badge) return;
  if (!c) {
    badge.textContent = "";
    return;
  }
  const before = Number(c.cash) || 0;
  const after = type === "deposit" ? before + amt : before - amt;
  badge.textContent = `Balance: ${money(before)} \u2192 ${money(after)}`;
}
async function submitOwMoney(event, type) {
  event.preventDefault();
  const ow = owState();
  const form = event.currentTarget;
  const fd = new FormData(form);
  const payload = {
    dealerId: ow.dealerId,
    customerId: fd.get("customerId"),
    financeId: fd.get("financeId") || "",
    amount: Number(fd.get("amount")) || 0,
    remarks: fd.get("remarks") || "",
    commissionPct: Number(fd.get("commissionPct")) || 0,
  };
  if (type === "deposit") payload.reference = fd.get("reference") || "";
  if (!payload.customerId) return flash("Customer chunein");
  if (!payload.amount) return flash("Amount daalein");
  if (type === "deposit" && payload.reference) {
    const chk = await postJson("/api/one-window/check-reference", {
      dealerId: ow.dealerId,
      financeId: payload.financeId,
      reference: payload.reference,
    }).catch(() => ({}));
    if (chk && chk.duplicate) {
      const info = (chk.existing || [])[0];
      if (
        !window.confirm(
          `Reference "${payload.reference}" pehle lag chuka${info ? ` (${info.customer} \xB7 ${money(info.amount)})` : ""}. Fraud to nahi? Phir bhi jama karein?`,
        )
      )
        return;
    }
  }
  try {
    const res = await postJson(`/api/one-window/${type}`, payload);
    form.reset();
    const b = document.getElementById("ow-badge-" + type);
    if (b) b.textContent = "";
    await refreshOneWindow();
    flash(
      `${type === "deposit" ? "Deposit" : "Withdraw"} ho gaya \u2014 ${money(res.before)} \u2192 ${money(res.after)}`,
    );
  } catch (error) {
    flash(feedMsg ? feedMsg(error, "Failed") : error.message);
  }
}
