    <div class="bp-rules-head"><span>Ledger \u2014 ${escapeHtml(L.title || "")}${L.type === "finance" && L.balance !== void 0 ? ` \xB7 Balance ${rs(L.balance)}` : ""}</span><button type="button" onclick="closeOwLedger()">&times;</button></div>
