async function refreshSecurity() {
  if (!isBetproOwner() || !state.token) return;
  try {
    const [ip, ses] = await Promise.all([
      getJson("/api/security/same-ip").catch(() => ({ groups: [] })),
      getJson("/api/admin/sessions").catch(() => ({ sessions: [] })),
    ]);
    state.sameIpGroups = ip.groups || [];
    state.loginSessions = ses.sessions || [];
  } catch {}
  render();
}
function securityView() {
  if (!isBetproOwner())
    return dealerShell(
      "Security",
      `<section class="dealer-panel"><div class="panel-head"><strong>Security</strong></div><p style="padding:18px">Owner only.</p></section>`,
    );
  if (!state.securityLoaded) {
    state.securityLoaded = true;
    refreshSecurity();
  }
  const groups = (state.sameIpGroups || []).filter(
    (g) => (g.users || []).length > 1,
  );
  const sessions = state.loginSessions || [];
  const ipRows = groups.length
    ? groups
        .map(
          (g) =>
            `<tr class="${g.count > 1 ? "flagged" : ""}"><td>${escapeHtml(g.ip)}</td><td>${g.count}</td><td>${(g.users || []).map(escapeHtml).join(", ")}</td><td>${g.count > 1 ? `<span class="cheat-sev cheat-sev-high">MULTI-ACCOUNT</span>` : "OK"}</td></tr>`,
        )
        .join("")
    : `<tr><td colspan="4" class="empty-note">No shared-IP groups.</td></tr>`;
  const sRows = sessions.length
    ? sessions
        .slice(0, 40)
        .map(
          (s) =>
            `<tr><td>${escapeHtml(s.username || "-")}</td><td>${escapeHtml(s.role || "-")}</td><td>${escapeHtml(s.ip || "-")}</td><td>${s.createdAt ? new Date(s.createdAt).toLocaleString("en-GB") : "-"}</td></tr>`,
        )
        .join("")
    : `<tr><td colspan="4" class="empty-note">No sessions.</td></tr>`;
  return dealerShell(
    "Security",
    `<section class="dealer-panel"><div class="panel-head"><strong>Same-IP / Multi-Account Detection</strong><button onclick="refreshSecurity()">${escapeHtml(T("Refresh"))}</button></div>
      <table class="highlight-table"><thead><tr><th>IP</th><th>Users</th><th>Accounts</th><th>Flag</th></tr></thead><tbody>${ipRows}</tbody></table></section>
    <section class="dealer-panel"><div class="panel-head"><strong>Recent Login Sessions</strong></div>
      <table class="highlight-table"><thead><tr><th>User</th><th>Role</th><th>IP</th><th>Time</th></tr></thead><tbody>${sRows}</tbody></table></section>`,
  );
}
