async function grantFeature(key, uid) {
  try {
    await postJson("/api/admin/features/registry/grant", {
      feature_key: key,
      user_id: uid,
    });
    state.featureAdd = null;
    state.featureAddQ = "";
    await refreshFeatures();
    flash("Granted");
  } catch (error) {
    flash(error.message || "Grant failed");
  }
}
async function revokeFeature(key, uid) {
  try {
    await postJson("/api/admin/features/registry/revoke", {
      feature_key: key,
      user_id: uid,
    });
    await refreshFeatures();
    flash("Revoked");
  } catch (error) {
    flash(error.message || "Revoke failed");
  }
}
function featureCardHtml(f, users) {
  const chips = (f.grantees || []).length
    ? (f.grantees || [])
        .map(
          (g) =>
            `<span class="feat-chip"><span>${escapeHtml(g.username)}</span><button type="button" title="Revoke" onclick="revokeFeature('${f.key}','${g.userId}')">&times;</button></span>`,
        )
        .join("")
    : `<span class="feat-none">No grantees</span>`;
  if (f.locked) {
    return `<div class="feat-card feat-locked"><div class="feat-card-head"><strong>${escapeHtml(f.label)}</strong><span class="feat-lock">\u{1F512} Company-only</span></div><div class="feat-hint">${escapeHtml(f.hint)}</div></div>`;
  }
  const grantedIds = new Set((f.grantees || []).map((g) => g.userId));
  const q = String(state.featureAddQ || "")
    .trim()
    .toLowerCase();
  const adding = state.featureAdd === f.key;
  const wantCustomer = f.grantee === "customer";
  const pool = (users || []).filter((u) =>
    f.defaultRole
      ? u.role === f.defaultRole
      : f.cascade
        ? true
        : wantCustomer
          ? u.role === "bettor"
          : u.role !== "bettor",
  );
  const matches = adding
    ? pool
        .filter(
          (u) =>
            !grantedIds.has(u.id) &&
            (!q || u.username.toLowerCase().includes(q)),
        )
        .slice(0, 8)
    : [];
  const addBox = adding
    ? `<div class="feat-add"><input type="search" class="feat-search" placeholder="${f.cascade ? "Search dealer (poora downline) ya customer\u2026" : wantCustomer ? "Search customer\u2026" : "Search dealer/user\u2026"}" value="${escapeHtml(String(state.featureAddQ || ""))}" oninput="setFeatureAddQ(this.value)" autofocus>
        <div class="feat-add-list">${matches.length ? matches.map((u) => `<button type="button" onclick="grantFeature('${f.key}','${u.id}')">${escapeHtml(u.username)} <small>${escapeHtml(u.role)}</small></button>`).join("") : `<span class="feat-none">${q ? "No match" : "Type to search"}</span>`}</div></div>`
    : "";
  return `<div class="feat-card"><div class="feat-card-head"><strong>${escapeHtml(f.label)}</strong><button type="button" class="feat-add-btn" onclick="openFeatureAdd('${f.key}')">${adding ? "Close" : "+ Add"}</button></div>
    <div class="feat-hint">${escapeHtml(f.hint)}</div>
    <div class="feat-chips">${chips}</div>
    ${addBox}</div>`;
}
