async function inviteSaveSettings(form) {
  const body = {
    off: form.off.checked === true,
    linkDays: Number(form.linkDays.value) || 0,
    maxPerDay: Number(form.maxPerDay.value) || 0,
    maxPerIp: Number(form.maxPerIp.value) || 0,
  };
  if (
    body.off &&
    !window.confirm(
      "Poora feature BAND kar dein?\n\nHar dealer ka link foran mar jayega (jab tak wapas ON na karein).",
    )
  )
    return;
  try {
    await postJson("/api/admin/invite-settings", body);
    flash("Settings save ho gayin");
    await inviteAdminLoad(true);
  } catch (e) {
    flash(e.message);
  }
}
function featuresView() {
  if (!isBetproOwner())
    return dealerShell(
      "Features",
      `<section class="dealer-panel"><div class="panel-head"><strong>Features</strong></div><p style="padding:18px">Owner only.</p></section>`,
    );
  if (!state.featuresLoaded) {
    state.featuresLoaded = true;
    refreshFeatures();
  }
  const data = state.featuresData || {};
  const features = data.features || [];
  const cats = data.categories || [];
  const users = data.users || [];
  const tab = state.featuresTab || "all";
  const tabDefs = [
    ["all", "All Features"],
    ...cats.map((c) => [c.key, c.label]),
  ];
  const tabsHtml = tabDefs
    .map(
      ([k, label]) =>
        `<button type="button" class="feat-tab ${tab === k ? "active" : ""}" onclick="setFeaturesTab('${k}')">${escapeHtml(label)}</button>`,
    )
    .join("");
  const shown =
    tab === "all" ? features : features.filter((f) => f.category === tab);
  const cardsHtml = shown.length
    ? shown.map((f) => featureCardHtml(f, users)).join("")
    : `<div class="empty-note" style="padding:16px">No features in this tab.</div>`;
  const loading = !data.features
    ? `<div class="empty-note" style="padding:16px">Loading\u2026</div>`
    : "";
  return dealerShell(
    "Features",
    `${siteLinkSectionHtml()}${inviteOwnerSectionHtml()}${shareLockSectionHtml()}${allowedShareSectionHtml()}<section class="dealer-panel feat-panel">
      <div class="panel-head"><strong>FEATURES \u2014 Per-user grant/revoke; asar turant</strong><button onclick="refreshFeatures()">${escapeHtml(T("Refresh"))}</button></div>
      <div class="feat-tabs">${tabsHtml}</div>
      <div class="feat-grid">${loading || cardsHtml}</div>
    </section>`,
  );
}
async function refreshGlSheet() {
  if (!isBetproOwner() || !state.token) return;
  try {
    state.glSheet = await getJson("/api/admin/balance-sheet?withReconcile=1");
  } catch {}
  render();
}
async function rebuildGl() {
  const waitDone = async (id) => {
    for (let i = 0; i < 300; i++) {
      await new Promise((r) => setTimeout(r, 3e3));
      let s = null;
      try {
        s = await getJson("/api/admin/gl/rebuild/status");
      } catch {}
      const st = s && s.status;
      if (st && st.id === id && st.state !== "running") return st;
    }
    return null;
  };
  try {
    const r = await postJson("/api/admin/gl/rebuild", { dryRun: true });
    if (r && r.reconcile) {
      await refreshGlSheet();
      flash("General Ledger rebuilt");
      return;
    }
    if (!r || !r.started) {
      flash("Rebuild shuru nahi hua");
      return;
    }
    flash("GL ka hisab ho raha hai (dry-run)\u2026");
    const d = await waitDone(r.id);
    if (!d || d.state !== "done") {
      flash("Dry-run nakaam: " + ((d && d.error) || "waqt khatam"));
      return;
    }
    const rb = (d.result && d.result.rebuilt) || {};
    const df = (d.result && d.result.diff) || {};
    const msg = `Naya GL: ${rb.txnCount} txns \xB7 ${rb.entryCount} entries \xB7 wallet farq ${rb.walletMismatchCount} \xB7 unbalanced ${rb.unbalancedCount}
Mojooda GL: wallet farq ${df.currentWalletMismatches} \xB7 unbalanced ${df.currentUnbalanced}
Sirf mojooda me ${df.onlyInCurrent} txns (hat jayengi) \xB7 sirf naye me ${df.onlyInRebuilt}

Asal rebuild karein? (chand second settlement rukegi; purani GL backup rehti hai)`;
    if (!window.confirm(msg)) return;
    const r2 = await postJson("/api/admin/gl/rebuild", { dryRun: false });
    if (!r2 || !r2.started) {
      flash("Rebuild shuru nahi hua");
      return;
    }
    flash("GL rebuild ho raha hai\u2026");
    const d2 = await waitDone(r2.id);
    await refreshGlSheet();
    flash(
      d2 && d2.state === "done"
        ? "General Ledger rebuilt"
        : "Rebuild nakaam: " + ((d2 && d2.error) || "waqt khatam"),
    );
  } catch (error) {
    flash(error.message || "Rebuild failed");
  }
}
function glSheetView() {
  if (!isBetproOwner())
    return dealerShell(
      "Ledger Sheet",
      `<section class="dealer-panel"><div class="panel-head"><strong>Ledger Sheet</strong></div><p style="padding:18px">Owner only.</p></section>`,
    );
  if (!state.glSheetLoaded) {
    state.glSheetLoaded = true;
    refreshGlSheet();
  }
  const data = state.glSheet || {};
  const sheet = data.sheet || {};
  const rec = data.reconcile || {};
  const plus = sheet.plus || [];
  const minus = sheet.minus || [];
  const totals = sheet.totals || {};
  const mismatches = rec.walletMismatches || [];
  const banner = `<div class="gl-banner ${rec.ok ? "ok" : "bad"}">${rec.ok ? "\u2713 GL balanced" : "\u26A0 GL DRIFT"} \u2014 ${rec.txnCount || 0} txns \xB7 ${rec.entryCount || 0} entries \xB7 ${rec.accountCount || 0} accounts \xB7 ${(rec.unbalanced || []).length} unbalanced \xB7 ${mismatches.length} wallet drift</div>`;
  const plRows = (arr) =>
    arr
      .map(
        (r) =>
          `<tr><td>${escapeHtml(r.label)}</td><td class="num">${rs(r.amount)}</td></tr>`,
      )
      .join("");
  const childRows =
    (sheet.childRows || [])
      .map(
        (c) =>
          `<tr><td>${escapeHtml(c.username || c.id || "-")}</td><td>${escapeHtml(c.role || "-")}</td><td class="num">${rs(c.amount ?? c.net ?? 0)}</td></tr>`,
      )
      .join("") ||
    `<tr><td colspan="3" class="empty-note">No downline rows.</td></tr>`;
  const driftRows = mismatches.length
    ? mismatches
        .map(
          (m) =>
            `<tr><td>${escapeHtml(m.userId || m.id || "-")}</td><td class="num">${rs(m.wallet ?? 0)}</td><td class="num">${rs(m.ledger ?? 0)}</td><td class="num bad">${rs((m.wallet ?? 0) - (m.ledger ?? 0))}</td></tr>`,
        )
        .join("")
    : `<tr><td colspan="4" class="empty-note">No wallet/ledger drift \u2014 clean.</td></tr>`;
  return dealerShell(
    "Ledger Sheet",
    `<section class="dealer-panel"><div class="panel-head"><strong>General Ledger / Balance Sheet</strong><button onclick="exportReportTable(this,'balance-sheet')">Excel</button><button onclick="rebuildGl()">Rebuild GL</button></div>
      ${banner}
      <div class="gl-two">
        <table class="highlight-table"><thead><tr><th>Plus</th><th>${escapeHtml(T("col:Amount"))}</th></tr></thead><tbody>${plRows(plus)}</tbody></table>
        <table class="highlight-table"><thead><tr><th>Minus</th><th>${escapeHtml(T("col:Amount"))}</th></tr></thead><tbody>${plRows(minus)}</tbody></table>
      </div>
      <div class="gl-total">Net: <strong>${rs(totals.net ?? totals.total ?? 0)}</strong></div>
    </section>
    <section class="dealer-panel"><div class="panel-head"><strong>Downline</strong></div><table class="highlight-table"><thead><tr><th>Account</th><th>Role</th><th>${escapeHtml(T("col:Amount"))}</th></tr></thead><tbody>${childRows}</tbody></table></section>
    <section class="dealer-panel"><div class="panel-head"><strong>Wallet \u2194 Ledger Drift Monitor</strong></div><table class="highlight-table"><thead><tr><th>User</th><th>Wallet</th><th>Ledger</th><th>Diff</th></tr></thead><tbody>${driftRows}</tbody></table></section>`,
  );
}
