async function lzaRefresh() {
  try {
    await refreshMoneyRequestsFromDb();
  } catch (e) {}
  render();
}
function lzaRows(kind) {
  const A = lzA();
  const all = (state.requests && state.requests[kind]) || [];
  const f = A.filter;
  const q = String(A.q || "")
    .trim()
    .toLowerCase();
  const stOf = (r) =>
    String(r.status) === "approved"
      ? "completed"
      : String(r.status || "pending");
  let rows = all.filter((r) => f === "all" || stOf(r) === f);
  if (q)
    rows = rows.filter((r) =>
      [
        r.user,
        r.transactionId,
        r.ref,
        r.reference,
        r.savedAccount && r.savedAccount.accountNumber,
        r.depositAccount && r.depositAccount.label,
      ].some((v) =>
        String(v || "")
          .toLowerCase()
          .includes(q),
      ),
    );
  rows.sort((a, b) =>
    String(b.createdAt || "").localeCompare(String(a.createdAt || "")),
  );
  return { rows, all, stOf };
}
function lzaSummary(kind) {
  const all = (state.requests && state.requests[kind]) || [];
  const done = all.filter((r) =>
    ["completed", "approved"].includes(String(r.status)),
  );
  return {
    total: all.length,
    pending: all.filter((r) => r.status === "pending").length,
    completed: done.length,
    amount: done.reduce((s, r) => s + (Number(r.amount) || 0), 0),
  };
}
async function lzaApprove(kind, id) {
  const A = lzA();
  const isDep = kind === "deposits";
  const body = { action: "approve" };
  if (!isDep && lzaHasBanks()) {
    const src = A.src[id] || "";
    if (!src) return flash("Select source (Cash or Bank) first");
    if (src === "bank" && !A.bank[id]) return flash("Select a bank");
    body.source = src;
    if (src === "bank") body.bank_id = A.bank[id];
  }
  const ok = window.confirm(
    isDep
      ? "Approve this deposit? The amount will be credited to the user immediately."
      : `Approve this withdrawal from ${String(body.source || "cash").toUpperCase()}?

User balance was already debited at request time.`,
  );
  if (!ok) return;
  try {
    await postJson(`/api/db/money-requests/${encodeURIComponent(id)}`, body);
    flash(isDep ? "Deposit approved" : "Withdrawal approved", "success");
    await refreshMoneyRequestsFromDb();
    await refreshAccountsFromDb().catch(() => {});
  } catch (e) {
    flash(e.message || (isDep ? "Failed to approve" : "Failed to approve"));
  }
  render();
}
async function lzaReject(kind, id) {
  const isDep = kind === "deposits";
  if (
    !window.confirm(
      isDep
        ? "Reject this deposit? This cannot be undone."
        : "Reject this withdrawal? The amount will be refunded to the user.",
    )
  )
    return;
  const reason = window.prompt("Rejection reason (optional):");
  if (reason === null) return;
  try {
    await postJson(`/api/db/money-requests/${encodeURIComponent(id)}`, {
      action: "reject",
      reason: String(reason || ""),
    });
    flash(
      isDep ? "Deposit rejected" : "Withdrawal rejected \u2014 amount refunded",
      "success",
    );
    await refreshMoneyRequestsFromDb();
    await refreshAccountsFromDb().catch(() => {});
  } catch (e) {
    flash(e.message || "Failed to reject");
  }
  render();
}
