function casinoLockCatalog() {
  return (
    state.marketLockCasino || { key: "casino", label: "Casino", lobbies: [] }
  );
}
function casinoGameBlocked(b, lobbyKey, gameKey) {
  return (
    b.has("casino") ||
    b.has(lobbyKey) ||
    (lobbyKey === "casino:bfg" && b.has("casino:betfair")) ||
    b.has(gameKey)
  );
}
function toggleCasinoLock(level, key) {
  const b = (state.marketLockBlocked = state.marketLockBlocked || new Set());
  const cat = casinoLockCatalog();
  const lobbies = cat.lobbies || [];
  if (level === "casino") {
    if (b.has("casino")) {
      b.delete("casino");
    } else {
      b.add("casino");
      for (const l of lobbies) {
        b.delete(l.key);
        for (const g of l.games || []) b.delete(g.key);
      }
      b.delete("casino:betfair");
    }
  } else if (level === "lobby") {
    const l = lobbies.find((x) => x.key === key);
    if (!l) return;
    const on = !(
      b.has("casino") ||
      b.has(key) ||
      (key === "casino:bfg" && b.has("casino:betfair"))
    );
    if (on) {
      b.add(key);
    } else {
      if (b.has("casino")) {
        b.delete("casino");
        for (const o of lobbies) if (o.key !== key) b.add(o.key);
      }
      b.delete(key);
      if (key === "casino:bfg") b.delete("casino:betfair");
      for (const g of l.games || []) b.delete(g.key);
    }
  } else if (level === "game") {
    const l = lobbies.find((x) => (x.games || []).some((g) => g.key === key));
    if (!l) return;
    const blocked = casinoGameBlocked(b, l.key, key);
    if (!blocked) {
      b.add(key);
    } else {
      if (b.has("casino")) {
        b.delete("casino");
        for (const o of lobbies) if (o.key !== l.key) b.add(o.key);
      }
      if (b.has(l.key) || (l.key === "casino:bfg" && b.has("casino:betfair"))) {
        b.delete(l.key);
        b.delete("casino:betfair");
        for (const g of l.games || []) if (g.key !== key) b.add(g.key);
      }
      b.delete(key);
    }
  }
  render();
}
function casinoLockSectionHtml(b) {
  const cat = casinoLockCatalog();
  if (!cat || !(cat.lobbies || []).length) return "";
  const casinoOn = !b.has("casino");
  const lobbies = (cat.lobbies || [])
    .map((l) => {
      const lobbyOn =
        casinoOn &&
        !b.has(l.key) &&
        !(l.key === "casino:bfg" && b.has("casino:betfair"));
      const games = (l.games || [])
        .map(
          (g) =>
            `<label class="ml-item ml-game${lobbyOn ? "" : " ml-dim"}"><input type="checkbox" ${casinoGameBlocked(b, l.key, g.key) ? "" : "checked"} onchange='toggleCasinoLock("game", ${JSON.stringify(g.key)})'> ${escapeHtml(g.label)}</label>`,
        )
        .join("");
      return `<div class="ml-lobby${casinoOn ? "" : " ml-dim"}"><label class="ml-item ml-lobby-head"><input type="checkbox" ${lobbyOn ? "checked" : ""} onchange='toggleCasinoLock("lobby", ${JSON.stringify(l.key)})'> <strong>${escapeHtml(l.label)}</strong> <span class="muted">(${(l.games || []).length} games)</span></label><div class="ml-games">${games}</div></div>`;
    })
    .join("");
  return `<hr class="ml-divider"><div class="ml-section ml-casino">
      <label class="ml-parent"><input type="checkbox" ${casinoOn ? "checked" : ""} onchange='toggleCasinoLock("casino")'> <strong>Casino</strong> <span class="muted">\u2014 tick hatao = poora casino band (dono lobbies, sab games)</span></label>
      ${lobbies}
    </div>`;
}
function toggleMarketLockSection(title) {
  const sec = MARKET_LOCK_SECTIONS.find((x) => x.title === title);
  if (!sec) return;
  state.marketLockBlocked = state.marketLockBlocked || new Set();
  const allOn = sec.items.every(([k]) => !state.marketLockBlocked.has(k));
  sec.items.forEach(([k]) => {
    if (allOn) state.marketLockBlocked.add(k);
    else state.marketLockBlocked.delete(k);
  });
  render();
}
async function saveMarketLock() {
  if (!state._mlLoaded)
    return flash(
      "Market-lock load nahi hui \u2014 save band (warna sab unlock ho jate). Refresh karein.",
    );
  const blocked = [...(state.marketLockBlocked || new Set())];
  try {
    await postJson("/api/admin/market-lock", { blocked });
  } catch (e) {
    if (
      !blocked.length &&
      /confirmClear|clear all market-locks/i.test(
        String((e && e.message) || ""),
      )
    ) {
      if (
        !window.confirm(
          "SAB markets ALLOW ho jayengi \u2014 pehle ke sab locks khatam. Pakka save karein?",
        )
      )
        return;
      try {
        await postJson("/api/admin/market-lock", {
          blocked,
          confirmClear: true,
        });
      } catch (e2) {
        return flash(feedMsg(e2, "Save failed"));
      }
    } else return flash(feedMsg(e, "Save failed"));
  }
  flash("Allowed market types saved");
  state._mlLoaded = false;
  state._mlLoading = false;
  state.marketLockBlocked = null;
  ensureMarketLock();
}
function casinoPlaceholderView(title) {
  const betsCard = (label, action) => `<div class="dc-card dc-bets">
      <div class="dc-card-head">${escapeHtml(label)} (0)${action ? ` <button type="button" class="dc-fbl">${escapeHtml(action)}</button>` : ""}</div>
      <div class="dc-th"><span>Runner</span><span>Price</span><span>Size</span><span>Better</span><span>Master</span></div>
    </div>`;
  return dealerShell(
    title,
    `<div class="dc-ph">
    <div class="dc-main"><div class="dc-card"><div class="dc-card-body"><div class="dc-note">No Active Market found!</div></div></div></div>
    <aside class="dc-side">${betsCard("Open Bets")}${betsCard("Matched Bets", "Full Bet List")}</aside>
  </div>`,
  );
}
function marketsView() {
  ensureMarketLock();
  const blocked = state.marketLockBlocked || new Set();
  const sections =
    MARKET_LOCK_SECTIONS.map((sec) => {
      const allOn = sec.items.every(([k]) => !blocked.has(k));
      const rows = sec.items
        .map(
          ([key, label]) => `
      <label class="ml-item"><input type="checkbox" ${blocked.has(key) ? "" : "checked"} onchange='toggleMarketLockKey(${JSON.stringify(key)})'> ${escapeHtml(label)}</label>`,
        )
        .join("");
      return `<div class="ml-section">
      <label class="ml-parent"><input type="checkbox" ${allOn ? "checked" : ""} onchange='toggleMarketLockSection(${JSON.stringify(sec.title)})'> <strong>${escapeHtml(sec.title)}</strong></label>
      ${rows}
    </div>`;
    }).join('<hr class="ml-divider">') + casinoLockSectionHtml(blocked);
  return dealerShell(
    "Bet Lock",
    `
    <div class="card">
      <div class="card-header"><strong>${escapeHtml(TX("Allowed Market Types ({x})", state.username))}</strong></div>
      <div class="card-body">${state._mlLoaded ? `${sections}<div class="ml-savebar"><button class="btn btn-primary" onclick="saveMarketLock()">Save</button></div>` : ""}</div>
    </div>`,
  );
}
function refreshAutoSettle() {
  if (!isBetproOwner() || !state.token) return;
  getJson("/api/admin/auto-settle")
    .then((d) => {
      state.autoSettle = d;
      render();
    })
    .catch(() => {});
}
function toggleAutoSettle() {
  const now = state.autoSettle && state.autoSettle.enabled;
  const next = !now;
  if (
    next &&
    !confirm(
      "Fancy khud-kaar settle CHALU karni hai?\n\nSaboot milne par bets khud settle honi shuru ho jayengi. Kabhi bhi yahin se band ki ja sakti hai.",
    )
  )
    return;
  apiCall("POST", "/api/admin/auto-settle", { enabled: next })
    .then((d) => {
      flash(d.enabled ? "Khud-kaar settle CHALU" : "Khud-kaar settle BAND");
      refreshAutoSettle();
    })
    .catch((e) => flash(e.message || "Nahi ho saka"));
}
function autoSettleCard() {
  if (!isBetproOwner()) return "";
  const d = state.autoSettle;
  if (!d)
    return `<section class="dealer-panel"><div class="panel-head"><strong>Fancy \u2014 Khud-kaar Settle</strong></div><div style="padding:14px">Laa raha hoon\u2026</div></section>`;
  const on = !!d.enabled;
  return `<section class="dealer-panel">
    <div class="panel-head"><strong>Fancy \u2014 Khud-kaar Settle</strong>
      <button class="green-btn" onclick="toggleAutoSettle()" style="background:${on ? "#00b181" : "#d0021b"}">${on ? "CHALU" : "BAND"}</button>
    </div>
    <table class="highlight-table"><tbody>
      <tr><td>Haalat</td><td><strong style="color:${on ? "#0b6121" : "#d0021b"}">${on ? "CHALU \u2014 saboot milne par khud settle hoti hain" : "BAND \u2014 sab kuch aap Settle panel se karte hain"}</strong></td></tr>
      <tr><td>Pichle 24 ghante me settle huin</td><td>${d.settledLast24h}</td></tr>
      <tr><td>Abhi khuli fancy bets</td><td>${d.openFancy}</td></tr>
      <tr><td>ROKI HUI (do darwazon ka ikhtilaf)</td><td><strong style="color:${d.holds ? "#d0021b" : "#0b6121"}">${d.holds}</strong>${d.holds ? " \u2014 Settle panel se dekhen" : ""}</td></tr>
      <tr><td>Aakhri settle</td><td>${d.lastSettle ? `${escapeHtml(d.lastSettle.selection)} \xB7 ${String(d.lastSettle.side).toUpperCase()} \xB7 ${d.lastSettle.status}${d.lastSettle.score != null ? ` \xB7 score ${d.lastSettle.score}` : ""}` : "\u2014"}</td></tr>
    </tbody></table>
  </section>`;
}
