function settingsView() {
  refreshAutoSettleOnce();
  return dealerShell("Game Settings", autoSettleCard());
}
async function refreshWithdrawalBlocks() {
  try {
    state.wblocks = await getJson("/api/admin/withdrawal-blocks");
  } catch (e) {
    state.wblocks = { pending: [], history: [], strict: [], error: e.message };
  }
  render();
}
function toggleCheatBlocksPanel() {
  state.cbOpen = !(state.cbOpen === true);
  if (state.cbOpen) refreshCheatBlocks();
  else render();
}
function submitCheatBlocksRange() {
  const v = (id) => {
    const el = document.getElementById(id);
    return el ? el.value : "";
  };
  state.cbFrom = v("cb-from") || reportIsoDate();
  state.cbTo = v("cb-to") || state.cbFrom;
  refreshCheatBlocks();
}
async function refreshCheatBlocks() {
  const f = state.cbFrom || reportIsoDate(),
    t = state.cbTo || f;
  const lo = Date.parse(`${f}T00:00:00`),
    hi = Date.parse(`${t}T23:59:59`);
  state.cbLoading = true;
  render();
  try {
    const r = await getJson(`/api/admin/cheating-blocks?from=${lo}&to=${hi}`);
    state.cheatingBlocks = Array.isArray(r.blocks) ? r.blocks : [];
  } catch (e) {
    state.cheatingBlocks = [];
  }
  state.cbLoading = false;
  render();
}
async function approveWithdrawalBlockGroup(userId, eventId, user, n) {
  if (
    !window.confirm(`Approve ${user} on this match?

Withdrawal hold is released and their held bets in this match settle on the declared result.`)
  )
    return;
  try {
    const r = await postJson("/api/admin/withdrawal-blocks/group/approve", {
      userId,
      eventId,
    });
    const b = r.bets || {};
    flash(
      `Released ${r.released} hold(s)${b.settled ? ` \xB7 ${b.settled} bet(s) settled` : ""}${b.unheld ? ` \xB7 ${b.unheld} bet(s) will settle normally` : ""}${r.remaining ? ` \xB7 ${r.remaining} other block(s) still hold withdrawal` : ""}`,
    );
    await refreshWithdrawalBlocks();
  } catch (e) {
    flash(e.message);
  }
}
async function voidWithdrawalBlockGroup(userId, eventId, user) {
  if (
    !window.confirm(`VOID ${user} on this match?

All their open bets in this match are voided (stake returned) and the withdrawal hold is released.`)
  )
    return;
  try {
    const r = await postJson("/api/admin/withdrawal-blocks/group/approve", {
      userId,
      eventId,
      mode: "void",
    });
    const b = r.bets || {};
    flash(
      `Voided ${b.voided || 0} bet(s) \xB7 released ${r.released} hold(s)${r.remaining ? ` \xB7 ${r.remaining} other block(s) still hold withdrawal` : ""}`,
    );
    await refreshWithdrawalBlocks();
  } catch (e) {
    flash(e.message);
  }
}
async function addStrictDealer() {
  const el = document.getElementById("wb-strict-user");
  const username = el ? String(el.value || "").trim() : "";
  if (username.length < 2) return flash("Username likhein");
  try {
    const r = await postJson("/api/admin/strict-fraud-dealers", { username });
    flash(`Added ${r.added} (${r.role})`);
    if (el) el.value = "";
    await refreshWithdrawalBlocks();
  } catch (e) {
    flash(e.message);
  }
}
async function removeStrictDealer(userId, username) {
  if (
    !window.confirm(`Remove ${username} from strict-mode list?

Future cheating alerts on their downline will no longer auto-block withdrawals.`)
  )
    return;
  try {
    await delJson(
      `/api/admin/strict-fraud-dealers?userId=${encodeURIComponent(userId)}`,
      { userId },
    );
    flash(`Removed ${username}`);
    await refreshWithdrawalBlocks();
  } catch (e) {
    flash(e.message);
  }
}
function withdrawalBlocksSection() {
  if (!state._wbLoaded) {
    state._wbLoaded = true;
    refreshWithdrawalBlocks();
  }
  const wb = state.wblocks || { pending: [], history: [], strict: [] };
  const sev = (s) =>
    `<span class="cheat-type ${s === "critical" ? "danger" : ""}">${escapeHtml(String(s || "high").toUpperCase())}</span>`;
  const when = (t) =>
    escapeHtml(
      String(t || "")
        .replace("T", " ")
        .slice(0, 16),
    );
  const strictRows = (wb.strict || []).length
    ? wb.strict
        .map(
          (s) =>
            `<tr><td><b>${escapeHtml(s.username)}</b> <small>${escapeHtml(s.role || "")}</small></td><td>${s.downline ? `${s.downline} customers downstream` : "direct watch (own account)"}</td><td>${s.active} active block(s)</td><td><button class="mini-btn danger" ${s.active ? 'disabled title="Approve all active blocks first"' : ""} onclick="removeStrictDealer('${escapeHtml(s.id)}','${escapeHtml(s.username)}')">Remove</button></td></tr>`,
        )
        .join("")
    : `<tr><td colspan="4" class="empty-note">Koi strict-mode dealer nahi.</td></tr>`;
  const pendRows = (wb.pending || []).length
    ? wb.pending
        .map(
          (g) =>
            `<tr><td><b>${escapeHtml(g.user)}</b></td><td>${escapeHtml(g.eventName || g.eventId || "-")}</td><td>${sev(g.severity)}</td><td class="cheat-trace">${(g.reasons || []).map(escapeHtml).join("<br>")}</td><td>${g.heldBets || 0} held${g.heldWithResult ? ` (${g.heldWithResult} result in)` : ""}${g.openBets ? ` \xB7 ${g.openBets} open` : ""}</td><td>${when(g.blockedAt)}</td><td><button class="mini-btn" onclick="approveWithdrawalBlockGroup('${escapeHtml(g.userId)}','${escapeHtml(g.eventId)}','${escapeHtml(g.user)}',${g.blocks.length})">Approve</button> <button class="mini-btn void" onclick="voidWithdrawalBlockGroup('${escapeHtml(g.userId)}','${escapeHtml(g.eventId)}','${escapeHtml(g.user)}')">Void</button></td></tr>`,
        )
        .join("")
    : `<tr><td colspan="7" class="empty-note">No customers blocked. \u2713</td></tr>`;
  const histRows = (wb.history || []).length
    ? wb.history
        .map(
          (b) =>
            `<tr><td>${escapeHtml(b.user)}</td><td>${sev(b.severity)}</td><td class="cheat-trace">${escapeHtml(b.blockedReason || "")}</td><td>${when(b.blockedAt)}</td><td>${escapeHtml(b.approvedByName || b.approvedBy || "")}</td><td>${when(b.approvedAt)}</td></tr>`,
        )
        .join("")
    : `<tr><td colspan="6" class="empty-note">No history yet.</td></tr>`;
  return `<h4 style="margin:14px 0 4px">STRICT-MODE WATCH LIST <small class="empty-note">cheating alert on themselves or their downline \u2192 withdrawal block</small></h4>
    <div style="display:flex;gap:6px;margin-bottom:6px"><input id="wb-strict-user" class="form-control" placeholder="Type 2+ letters \u2014 dealer / master / admin / customer\u2026" style="max-width:320px"><button class="mini-btn" onclick="addStrictDealer()">Add</button><button class="mini-btn" onclick="refreshWithdrawalBlocks()">Refresh</button></div>
    <table class="highlight-table"><thead><tr><th>User</th><th>Scope</th><th>Blocks</th><th></th></tr></thead><tbody>${strictRows}</tbody></table>
    <h4 style="margin:14px 0 4px">PENDING BLOCK RELEASES (${(wb.pending || []).length}) <small class="empty-note">customers awaiting approval \u2014 withdrawal 403 jab tak release na ho</small></h4>
    <table class="highlight-table cheat-table"><thead><tr><th>User</th><th>Match</th><th>Severity</th><th>Reason</th><th>Held Bets</th><th>Blocked At</th><th>Action</th></tr></thead><tbody>${pendRows}</tbody></table>
    <h4 style="margin:14px 0 4px">APPROVED BLOCKS HISTORY (${(wb.history || []).length}) <small class="empty-note">all releases (audit trail)</small></h4>
    <table class="highlight-table cheat-table"><thead><tr><th>User</th><th>Severity</th><th>Reason</th><th>Blocked At</th><th>Approved By</th><th>Approved At</th></tr></thead><tbody>${histRows}</tbody></table>`;
}
function refreshCheatingPage() {
  const tab = state.cheatingTab || "alerts";
  if (
    typeof fpTabBody === "function" &&
    [
      "alerts",
      "clean",
      "review",
      "pending",
      "watched",
      "byuser",
      "byevent",
      "voids",
      "dealer",
      "grey",
    ].includes(tab)
  ) {
    fpLoad();
    return;
  }
  refreshFraudData();
}
async function refreshFraudData() {
  if (!isBetproOwner() || !state.token) return;
  try {
    const [alertsRes, rulesRes, blocksRes] = await Promise.all([
      getJson("/api/security/fraud-alerts").catch(() => ({ alerts: [] })),
      getJson("/api/admin/fraud/rules").catch(() => ({
        rules: [],
        settings: {},
      })),
      Promise.resolve(null),
    ]);
    state.fraudAlerts = Array.isArray(alertsRes.alerts) ? alertsRes.alerts : [];
    state.fraudRules = Array.isArray(rulesRes.rules) ? rulesRes.rules : [];
    state.fraudSettings = rulesRes.settings || { benefitGate: false };
    void blocksRes;
  } catch {}
  render();
}
function setCheatingTab(tab) {
  state.cheatingTab = tab;
  if (
    typeof fpTabBody === "function" &&
    [
      "alerts",
      "clean",
      "review",
      "pending",
      "watched",
      "byuser",
      "byevent",
      "voids",
      "dealer",
      "send",
      "grey",
    ].includes(tab)
  ) {
    const st = fpState();
    st.tab = tab;
    st.drill = null;
    fpLoad();
    return;
  }
  render();
}
async function reviewFraudAlert(id, status) {
  try {
    await patchJson(`/api/security/fraud-alerts/${id}`, { status });
    await refreshFraudData();
    flash(`Alert ${status}`);
  } catch (error) {
    flash(error.message || "Failed");
  }
}
async function approveCheatBlock(betId) {
  try {
    await postJson("/api/admin/cheating-blocks/approve", { betId });
    await refreshFraudData();
    await refreshAccountsFromDb().catch(() => {});
    flash("Released \u2014 bet settle hogi");
  } catch (error) {
    flash(error.message || "Failed");
  }
}
async function voidFraudBet(betId) {
  if (!betId) {
    flash("No bet linked to this alert");
    return;
  }
  const reason = window.prompt(
    "Ye bet kis wajah se void ki ja rahi hai?\n\n(Ye wajah ledger me aur match ki bets wali jagah par likhi jayegi \u2014 user bhi dekh sakta hai.)",
    "",
  );
  if (reason === null) return;
  const clean = String(reason || "").trim();
  if (clean.length < 3) {
    flash("Wajah likhna zaroori hai", "error");
    return;
  }
  try {
    const r = await postJson(
      `/api/admin/fraud/void/${encodeURIComponent(betId)}`,
      { reason: clean },
    );
    if (typeof fpLoad === "function" && state.fp) await fpLoad();
    else await refreshFraudData();
    await refreshAccountsFromDb().catch(() => {});
    flash(
      `Bet VOID \u2014 paisa wapis${r && r.wasStatus && ["won", "lost"].includes(r.wasStatus) ? ` (settlement bhi ulti ki gayi)` : ""}`,
      "success",
    );
  } catch (error) {
    flash(error.message || "Void failed", "error");
  }
}
async function addFraudRule() {
  const v = (id) => (document.getElementById(id) || {}).value;
  try {
    await postJson("/api/admin/fraud/rules", {
      name: v("fr-name") || "Rule",
      type: v("fr-type") || "shift",
      rateMin: Number(v("fr-min")) || 0,
      rateMax: Number(v("fr-max")) || 1e3,
      diffThreshold: Number(v("fr-diff")) || 0,
      severity: v("fr-sev") || "medium",
    });
    await refreshFraudData();
    flash("Rule added");
  } catch (error) {
    flash(error.message || "Failed");
  }
}
