function openLedgerPopup(id, group = "users", type = "", focus = false) {
  const account = findAccount(group, id) || findAccountAnywhere(id);
  const typeParam = type ? `&type=${encodeURIComponent(type)}` : "";
  const jumpParam =
    typeof focus === "string" && focus
      ? `&focus=${encodeURIComponent(focus)}`
      : focus
        ? "&last=1"
        : "";
  const url = `${routePaths.ledger}?accountId=${encodeURIComponent(id)}${typeParam}${jumpParam}`;
  const popup = window.open(
    url,
    `bpexch_ledger_${id}_${type || "all"}`,
    "height=800,width=950,titlebar=0,menubar=0,resizable=yes,scrollbars=yes",
  );
  if (!popup || !account) {
    state.ledgerType = type;
    state.modal = { type: "ledger", id, group };
    render();
    return;
  }
  popup.focus();
}
function reportDate() {
  const date = new Date();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${month}/${day}/${date.getFullYear()}`;
}
function reportIsoDate() {
  const date = new Date();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  const day = String(date.getDate()).padStart(2, "0");
  return `${date.getFullYear()}-${month}-${day}`;
}
function ledgerDefaultFromParts() {
  const d = new Date();
  const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  return { iso, clock: "00:00" };
}
function clockToDisplay(clock24) {
  const m = String(clock24 || "").match(/^(\d{1,2}):(\d{2})/);
  if (!m) return "";
  let h = Number(m[1]);
  const ampm = h >= 12 ? "PM" : "AM";
  h = h % 12 || 12;
  return `${h}:${m[2]} ${ampm}`;
}
function parseClockDisplay(text, fallback) {
  const m = String(text || "")
    .trim()
    .match(/^(\d{1,2})[:.](\d{2})\s*(am|pm)?$/i);
  if (!m) return fallback;
  let h = Number(m[1]);
  const ap = (m[3] || "").toLowerCase();
  if (ap === "pm" && h < 12) h += 12;
  if (ap === "am" && h === 12) h = 0;
  if (h > 23 || Number(m[2]) > 59) return fallback;
  return `${String(h).padStart(2, "0")}:${m[2]}`;
}
function ledgerIsoToMdy(iso) {
  const m = String(iso || "").match(/^(\d{4})-(\d{2})-(\d{2})$/);
  return m ? `${m[2]}/${m[3]}/${m[1]}` : String(iso || "");
}
function reportDateControl(which) {
  const isFrom = which === "rfrom";
  const cur = String(
    (isFrom ? state.reportFrom : state.reportTo) ||
      `${reportIsoDate()}T${isFrom ? "00:00" : "23:59"}`,
  );
  const [dateVal, clockRaw] = cur.split("T");
  const clockVal = (clockRaw || (isFrom ? "00:00" : "23:59")).slice(0, 5);
  return `<span class="ledger-date-box">
    <input type="hidden" id="ledger-${which}-date" value="${dateVal}">
    <input type="text" class="ledger-date-text" id="ledger-${which}-datetext" value="${ledgerIsoToMdy(dateVal)}" readonly spellcheck="false" autocomplete="off" onclick="bpLedgerCalToggle('${which}', event)">
    <input type="text" class="ledger-time-text" id="ledger-${which}-time" value="${clockToDisplay(clockVal).split(" ")[0] || ""}" spellcheck="false" autocomplete="off" onchange="ledgerTimeCommitSplit('${which}', this.value)">
    <span class="ledger-ampm" id="ledger-${which}-ampm" onclick="ledgerAmpmToggle('${which}')">${clockToDisplay(clockVal).split(" ")[1] || "AM"}</span>
    <button class="ledger-calendar" type="button" tabindex="-1" aria-label="Pick date" onclick="bpLedgerCalToggle('${which}', event)"><i class="fas fa-calendar"></i></button>
  </span>`;
}
function ledgerDateControl(which) {
  const isFrom = which === "from";
  const def = ledgerDefaultFromParts();
  const dateVal =
    (isFrom ? state.ledgerFromDate : state.ledgerToDate) ||
    (isFrom ? def.iso : reportIsoDate());
  const clockVal =
    (isFrom ? state.ledgerFromClock : state.ledgerToClock) ||
    (isFrom ? def.clock : "23:59");
  return `<span class="ledger-date-box">
    <input type="hidden" id="ledger-${which}-date" value="${dateVal}">
    <input type="text" class="ledger-date-text" id="ledger-${which}-datetext" value="${ledgerIsoToMdy(dateVal)}" readonly spellcheck="false" autocomplete="off" onclick="bpLedgerCalToggle('${which}', event)">
    <input type="text" class="ledger-time-text" id="ledger-${which}-time" value="${clockToDisplay(clockVal).split(" ")[0] || ""}" spellcheck="false" autocomplete="off" onchange="ledgerTimeCommitSplit('${which}', this.value)">
    <span class="ledger-ampm" id="ledger-${which}-ampm" onclick="ledgerAmpmToggle('${which}')">${clockToDisplay(clockVal).split(" ")[1] || "AM"}</span>
    <button class="ledger-calendar" type="button" tabindex="-1" aria-label="Pick date" onclick="bpLedgerCalToggle('${which}', event)"><i class="fas fa-calendar"></i></button>
  </span>`;
}
function ledgerTimeCommitSplit(which, text) {
  const ap =
    (document.getElementById(`ledger-${which}-ampm`) || {}).textContent || "AM";
  ledgerInputCommit(which, "time", `${String(text || "").trim()} ${ap}`);
}
function ledgerAmpmToggle(which) {
  const el = document.getElementById(`ledger-${which}-ampm`);
  if (!el) return;
  el.textContent = el.textContent.trim() === "AM" ? "PM" : "AM";
  const t = (document.getElementById(`ledger-${which}-time`) || {}).value || "";
  ledgerTimeCommitSplit(which, t);
}
let _bpLedCal = null;
let _bpLedCalUnclipped = [];
function bpLedCalUnclip(host) {
  bpLedCalReclip();
  let el = host && host.parentElement;
  while (el && el !== document.body && el.nodeType === 1) {
    let cs = null;
    try {
      cs = window.getComputedStyle(el);
    } catch (e) {
      cs = null;
    }
    if (cs) {
      for (const prop of ["overflow", "overflowX", "overflowY"]) {
        if (cs[prop] && cs[prop] !== "visible") {
          _bpLedCalUnclipped.push([el, prop, el.style[prop]]);
          el.style[prop] = "visible";
        }
      }
    }
    el = el.parentElement;
  }
}
function bpLedCalReclip() {
  for (const [el, prop, old] of _bpLedCalUnclipped) {
    try {
      el.style[prop] = old;
    } catch (e) {}
  }
  _bpLedCalUnclipped = [];
}
function bpLedCalFit(el, host) {
  if (!el || !host) return;
  try {
    const vw = document.documentElement.clientWidth;
    const pad = 8;
    let r = el.getBoundingClientRect();
    if (r.right > vw - pad) {
      el.style.left = "auto";
      el.style.right = "0";
      r = el.getBoundingClientRect();
    }
    if (r.left < pad) {
      const hostRect = host.getBoundingClientRect();
      el.style.right = "auto";
      el.style.left = `${pad - hostRect.left}px`;
    }
  } catch (e) {}
}
function bpLedCalClose() {
  const pop = document.querySelector(".bp-ledcal");
  if (pop) pop.remove();
  bpLedCalReclip();
  _bpLedCal = null;
}
function bpLedgerCalToggle(which, ev) {
  if (ev) ev.stopPropagation();
  const open = document.querySelector(".bp-ledcal");
  const wasSame = open && open.getAttribute("data-which") === which;
  if (open) bpLedCalClose();
  if (wasSame) return;
  const iso =
    (document.getElementById(`ledger-${which}-date`) || {}).value ||
    reportIsoDate();
  const p = iso.split("-").map(Number);
  _bpLedCal = { which, y: p[0], m: (p[1] || 1) - 1 };
  bpLedgerCalRender();
  if (!window._bpLedCalDoc) {
    window._bpLedCalDoc = true;
    document.addEventListener("click", (e) => {
      const pop = document.querySelector(".bp-ledcal");
      if (
        pop &&
        !pop.contains(e.target) &&
        !e.target.closest(".ledger-date-box")
      )
        bpLedCalClose();
    });
  }
}
function bpLedgerCalShift(d, ev) {
  if (ev) ev.stopPropagation();
  if (!_bpLedCal) return;
  _bpLedCal.m += d;
  if (_bpLedCal.m < 0) {
    _bpLedCal.m = 11;
    _bpLedCal.y -= 1;
  }
  if (_bpLedCal.m > 11) {
    _bpLedCal.m = 0;
    _bpLedCal.y += 1;
  }
  const open = document.querySelector(".bp-ledcal");
  if (open) open.remove();
  bpLedgerCalRender();
}
function bpLedgerCalPick(iso, ev) {
  if (ev) ev.stopPropagation();
  if (!_bpLedCal) return;
  const which = _bpLedCal.which;
  const hid = document.getElementById(`ledger-${which}-date`);
  const txt = document.getElementById(`ledger-${which}-datetext`);
  if (hid) hid.value = iso;
  if (txt) txt.value = ledgerIsoToMdy(iso);
  ledgerInputCommit(which, "date", iso);
  bpLedCalClose();
}
function bpLedgerCalRender() {
  if (!_bpLedCal) return;
  const { which, y, m } = _bpLedCal;
  const box = document.getElementById(`ledger-${which}-date`);
  const host = box && box.closest(".ledger-date-box");
  if (!host) return;
  const sel = String(
    (document.getElementById(`ledger-${which}-date`) || {}).value || "",
  );
  const first = new Date(y, m, 1);
  const start = new Date(y, m, 1 - first.getDay());
  const MON = [
    "January",
    "February",
    "March",
    "April",
    "May",
    "June",
    "July",
    "August",
    "September",
    "October",
    "November",
    "December",
  ];
  let days = "";
  for (let i = 0; i < 42; i++) {
    const d = new Date(
      start.getFullYear(),
      start.getMonth(),
      start.getDate() + i,
    );
    const iso = `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
    const cls = `bp-ledcal-day${d.getMonth() !== m ? " oth" : ""}${iso === sel ? " sel" : ""}`;
    days += `<span class="${cls}" onclick="bpLedgerCalPick('${iso}', event)">${d.getDate()}</span>`;
  }
  const el = document.createElement("div");
  el.className = "bp-ledcal";
  el.setAttribute("data-which", which);
  el.onclick = (e) => e.stopPropagation();
  el.innerHTML = `
    <div class="bp-ledcal-head">
      <button type="button" class="bp-ledcal-nav" onclick="bpLedgerCalShift(-1, event)">&lsaquo;</button>
      <span class="bp-ledcal-title"><b>${MON[m]}</b><b>${y}</b></span>
      <button type="button" class="bp-ledcal-nav" onclick="bpLedgerCalShift(1, event)">&rsaquo;</button>
    </div>
    <div class="bp-ledcal-grid">
      ${["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"].map((d) => `<span class="bp-ledcal-dow">${d}</span>`).join("")}
      ${days}
    </div>`;
  bpLedCalUnclip(host);
  host.appendChild(el);
  bpLedCalFit(el, host);
}
function ledgerInputCommit(which, kind, value) {
  if (which === "rfrom" || which === "rto") {
    const key = which === "rfrom" ? "reportFrom" : "reportTo";
    const cur = String(
      state[key] ||
        `${reportIsoDate()}T${which === "rfrom" ? "00:00" : "23:59"}`,
    );
    const [dPart, tPart] = cur.split("T");
    if (kind === "date") {
      if (value)
        state[key] =
          `${value}T${tPart || (which === "rfrom" ? "00:00" : "23:59")}`;
    } else {
      const parsed = parseClockDisplay(
        value,
        tPart || (which === "rfrom" ? "00:00" : "23:59"),
      );
      state[key] = `${dPart}T${parsed}`;
    }
    return;
  }
  const isFrom = which === "from";
  if (kind === "date") {
    if (!value) return;
    if (isFrom) state.ledgerFromDate = value;
    else state.ledgerToDate = value;
  } else {
    const def = ledgerDefaultFromParts();
    const parsed = parseClockDisplay(
      value,
      isFrom
        ? state.ledgerFromClock || def.clock
        : state.ledgerToClock || "23:59",
    );
    if (isFrom) state.ledgerFromClock = parsed;
    else state.ledgerToClock = parsed;
  }
}
function submitLedgerFilter() {
  const val = (id) => {
    const el = document.getElementById(id);
    return el ? el.value : "";
  };
  state.ledgerFromDate = val("ledger-from-date") || state.ledgerFromDate;
  state.ledgerToDate = val("ledger-to-date") || state.ledgerToDate;
  const def = ledgerDefaultFromParts();
  const timeWithAp = (w) =>
    `${val(`ledger-${w}-time`)} ${(document.getElementById(`ledger-${w}-ampm`) || {}).textContent || ""}`.trim();
  state.ledgerFromClock = parseClockDisplay(
    timeWithAp("from"),
    state.ledgerFromClock || def.clock,
  );
  state.ledgerToClock = parseClockDisplay(
    timeWithAp("to"),
    state.ledgerToClock || "23:59",
  );
  state.ledgerPage = 1;
  state.stmtCache = null;
  state.stmtErrKey = null;
  state.stmtLoading = null;
  if (typeof refreshExBetsFromApi === "function")
    refreshExBetsFromApi().catch(() => {});
  if (typeof refreshAccountsFromDb === "function")
    refreshAccountsFromDb()
      .then(() => render())
      .catch(() => {});
  render();
}
function ledgerEntryKind(text) {
  const t = String(text || "").toLowerCase();
  if (/credit/.test(t)) return "credit";
  if (/p\/l|won|lost|win|loss|settle|bet|result/.test(t)) return "pl";
  if (/cash|deposit|withdraw/.test(t)) return "cash";
  return "";
}
function refreshAutoSettleOnce() {
  if (!isBetproOwner() || state._autoSettleLoading) return;
  if (state.autoSettle && Date.now() - (state._autoSettleAt || 0) < 15e3)
    return;
  state._autoSettleLoading = true;
  state._autoSettleAt = Date.now();
  getJson("/api/admin/auto-settle")
    .then((d) => {
      state.autoSettle = d;
      state._autoSettleLoading = false;
      render();
    })
    .catch(() => {
      state._autoSettleLoading = false;
    });
}
function tpAdminRefresh() {
  if (state._tpAdminLoading) return Promise.resolve();
  state._tpAdminLoading = true;
  const avLoad = (base) =>
    Promise.all([
      getJson(`${base}/mode`).catch(() => null),
      getJson(`${base}/target`).catch(() => null),
      getJson(`${base}/audit`).catch(() => ({ rows: [] })),
      getJson(`${base}/steer`).catch(() => null),
    ]).then(([mode, target, audit, steer]) => ({
      mode,
      target,
      audit: (audit && audit.rows) || [],
      steer,
    }));
  return Promise.all([
    getJson("/api/admin/games/edge"),
    getJson("/api/admin/games/settings"),
    getJson("/api/admin/games/stuck-rounds").catch(() => ({ rounds: [] })),
    getJson("/api/admin/games/casino-watch").catch(() => ({ rows: [] })),
    getJson("/api/admin/games/phases").catch(() => ({ lists: [], games: [] })),
    getJson("/api/admin/games/ceiling").catch(() => ({
      defaults: {},
      rows: [],
      error: true,
    })),
    avLoad("/api/aviator"),
    avLoad("/api/aviator-classic"),
  ])
    .then(([edge, settings, stuck, cw, phases, ceil, avx, avc]) => {
      state.tpAdmin = {
        edge,
        games: settings.games || [],
        stuck: (stuck && stuck.rounds) || [],
        casinoWatch: cw || { rows: [] },
        phases: phases || { lists: [], games: [] },
        ceiling: ceil || { defaults: {}, rows: [] },
        aviator: { x: avx, c: avc },
        loadedAt: Date.now(),
      };
      state.tpAdminError = "";
    })
    .catch((e) => {
      state.tpAdminError = String((e && e.message) || "Load failed");
    })
    .finally(() => {
      state._tpAdminLoading = false;
    });
}
