function tpSaveTimings(form) {
  const slug = form.getAttribute("data-slug");
  const body = { slug };
  [
    "betting_seconds",
    "suspend_seconds",
    "result_seconds",
    "card_speed_multiplier",
  ].forEach((k) => {
    const el = form.querySelector(`[name=${k}]`);
    const v = el ? el.value : "";
    if (v !== "") body[k] = Number(v);
  });
  if (body.card_speed_multiplier !== void 0)
    body.animation_speed_multiplier = body.card_speed_multiplier;
  return tpAdminAction(
    "PUT",
    "/api/admin/games/settings",
    body,
    `${slug}: timings saved`,
  );
}
function tpSavePhases(form) {
  const slug = form.getAttribute("data-slug");
  const values = {};
  form.querySelectorAll("input[data-phase]").forEach((el) => {
    const v = String(el.value || "").trim();
    values[el.getAttribute("data-phase")] = v === "" ? null : Number(v);
  });
  const speedEl = form.querySelector("input[name=card_speed_multiplier]");
  const chain = tpAdminAction(
    "PUT",
    "/api/admin/games/phases",
    { slug, values },
    `${slug}: phase timings saved (agle round se)`,
  );
  if (
    speedEl &&
    speedEl.value !== "" &&
    Number(speedEl.value) !== Number(speedEl.getAttribute("data-was"))
  ) {
    const sp = Number(speedEl.value);
    return chain.then(() =>
      tpAdminAction(
        "PUT",
        "/api/admin/games/settings",
        { slug, card_speed_multiplier: sp, animation_speed_multiplier: sp },
        `${slug}: speed ${sp}`,
      ),
    );
  }
  return chain;
}
function tpResetPhases(slug, keys) {
  const values = {};
  String(keys || "")
    .split(",")
    .filter(Boolean)
    .forEach((k) => {
      values[k] = null;
    });
  return tpAdminAction(
    "PUT",
    "/api/admin/games/phases",
    { slug, values },
    `${slug}: sab phases default par`,
  );
}
function tpPhasesSection(ph) {
  const lists = (ph && ph.lists) || [];
  const games = (ph && ph.games) || [];
  if (!lists.length)
    return `<section class="card"><div class="plain-card-header"><strong>Games \u2014 ON/OFF + phase timings</strong></div><div class="card-body"><p class="muted">Loading\u2026</p></div></section>`;
  const row = (g) => {
    const inputs = g.phases
      .map(
        (p) =>
          `<label class="tp-ph" title="${escapeHtml(p.label)} \u2014 default ${p.def}s (${p.min}\u2013${p.max})"><span>${escapeHtml(p.label)}</span><input type="number" min="${p.min}" max="${p.max}" step="1" data-phase="${escapeHtml(p.key)}" value="${p.value != null ? p.value : ""}" placeholder="${p.def}" class="${p.value != null && Number(p.value) !== Number(p.def) ? "tp-ovr" : ""}"></label>`,
      )
      .join("");
    const keys = g.phases.map((p) => p.key).join(",");
    const speed =
      g.list === "crash"
        ? ""
        : `<label class="tp-ph tp-ph-speed" title="Card / animation speed (1 = normal)"><span>Speed</span><input type="number" name="card_speed_multiplier" step="0.05" min="0.25" max="3" value="${g.card_speed}" data-was="${g.card_speed}"></label>`;
    const body = g.phases.length
      ? `<form class="tp-phases" data-slug="${escapeHtml(g.slug)}" onsubmit="event.preventDefault(); tpSavePhases(this)">${inputs}${speed}<button type="submit" class="btn-sm">Save</button> <button type="button" class="btn-sm tp-reset" onclick='tpResetPhases(${JSON.stringify(g.slug)}, ${JSON.stringify(keys)})'>Reset</button></form>`
      : `<span class="muted">koi round-timer nahi (khilari-driven)</span>`;
    return `<tr><td class="tp-gname">${escapeHtml(g.game_name)}<small class="tp-role">${escapeHtml(g.slug)}</small></td>
      <td><label class="tp-switch"><input type="checkbox" ${g.is_active ? "checked" : ""} onchange='tpToggleGame(${JSON.stringify(g.slug)}, this.checked)'> ${g.is_active ? "ON" : "OFF"}</label></td>
      <td>${body}</td></tr>`;
  };
  return lists
    .map((l) => {
      const gs = games.filter((g) => g.list === l.key);
      return `<section class="card tp-list tp-list-${escapeHtml(l.key)}"><div class="plain-card-header"><strong>${escapeHtml(l.label)}</strong> <small class="muted">${escapeHtml(l.note)} \xB7 ${gs.length} games</small></div><div class="card-body">
      <p class="muted">Har khana seconds me. Khali = default (khane me halka likha). Badla hua khana peela. Save \u2192 agle round se (30s ke andar), restart nahi. Reset = sab default.</p>
      <table class="table table-bordered tp-table tp-phase-table"><thead><tr><th>Game</th><th>Status</th><th>Phases (seconds)</th></tr></thead><tbody>${gs.map(row).join("")}</tbody></table>
    </div></section>`;
    })
    .join("");
}
