function fpTabBody(tab) {
  const s = fpState();
  const dataFor = {
    alerts: "data",
    clean: "data",
    review: "data",
    byuser: "byUser",
    byevent: "byEvent",
    pending: "pending",
    watched: "watched",
    voids: "voids",
    dealer: "dealer",
    grey: "grey",
  }[tab];
  const missing = dataFor ? !s[dataFor] : false;
  if (s.tab !== tab || missing) {
    s.tab = tab;
    if (s.tab !== tab) s.drill = null;
    if (!s.loading) setTimeout(fpLoad, 0);
  }
  if (["alerts", "clean", "review"].includes(tab)) return fpAlertsTab();
  if (tab === "byuser") return fpByUserTab();
  if (tab === "byevent") return fpByEventTab();
  if (tab === "pending") return fpPendingTab();
  if (tab === "watched") return fpWatchedTab();
  if (tab === "voids") return fpVoidsTab();
  if (tab === "dealer") return fpDealerTab();
  if (tab === "grey") return fpGreyTab();
  if (tab === "send") return fpSendTab();
  return "";
}
