function ledgerEntryCategory(entry, account) {
  const meta =
    typeof ledgerBetMeta === "function" ? ledgerBetMeta(entry.betId) : null;
  const bet = ledgerStateBet(entry.betId) || meta;
  const slug =
    (bet && (bet.slug || bet.game)) || (meta && meta.game) || entry.game || "";
  const evId = (bet && bet.eventId) || (meta && meta.eventId) || "";
  const isCasino = slug && !(evId && String(evId) !== "undefined");
  if (isCasino) {
    const desc = String((meta && meta.desc) || (bet && bet.desc) || "");
    if (/^TeenPatti Studio/i.test(desc)) return "TeenPatti Studio";
    if (/^BetFairGame/i.test(desc)) return "BetFairGames";
    const known =
      typeof EX_GAME_LABELS !== "undefined" &&
      EX_GAME_LABELS.some(
        (g) =>
          String(g.slug || g.id || "").toLowerCase() ===
          String(slug).toLowerCase(),
      );
    return known ? "BetFairGames" : "TeenPatti Studio";
  }
  if (bet) {
    if (
      String(bet.market || (meta && meta.market) || "").toLowerCase() ===
      "fancy"
    )
      return "Fancy";
    const sportName = bet.sport || (meta && meta.sport) || "";
    if (sportName) {
      const s = String(sportName).trim();
      const known = PL_CATEGORY_ORDER.find(
        (c) => c.toLowerCase() === s.toLowerCase(),
      );
      return known || s.replace(/w/g, (ch) => ch.toUpperCase());
    }
  }
  return "Other";
}
