function profitLossCategories(account, showAll) {
  const byCat = new Map();
  if (showAll) PL_DEFAULT_CATEGORIES.forEach((c) => byCat.set(c, 0));
  profitLossBetEntries(account).forEach((e) => {
    const cat = ledgerEntryCategory(e, account);
    byCat.set(cat, (byCat.get(cat) || 0) + num(e.amount));
  });
  const idx = (n) => {
    const i = PL_CATEGORY_ORDER.indexOf(n);
    return i === -1 ? 999 : i;
  };
  return [...byCat.entries()]
    .map(([name, amount]) => ({ name, amount }))
    .sort((a, b) => idx(a.name) - idx(b.name) || a.name.localeCompare(b.name));
}
