function selectedEditAccount() {
  const wanted = state.editAccountId;
  const found =
    findAccount(state.editAccountGroup, wanted) || findAccountAnywhere(wanted);
  if (found) {
    state.editAccountId = found.id;
    state.editAccountGroup = accountGroup(found);
    return found;
  }
  const first = state.users[0] || state.dealers[0] || null;
  if (!wanted && first) {
    state.editAccountId = first.id;
    state.editAccountGroup = accountGroup(first);
    return first;
  }
  return { id: wanted || "", username: "", role: "bettor" };
}
