function eventTeams(eventName) {
  const parts = String(eventName || "").split(/\s+vs?\s+/i);
  return { team1: (parts[0] || "").trim(), team2: (parts[1] || "").trim() };
}
function resolveRunnerName(name, bets) {
  const key = (s) =>
    String(s || "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .replace(/[^a-z0-9]/g, "");
  const toks = (s) =>
    String(s || "")
      .toLowerCase()
      .replace(/&/g, " and ")
      .split(/[^a-z0-9]+/)
      .filter(Boolean);
  const want = key(name);
  if (!want) return name;
  const sels = [
    ...new Set(
      (bets || [])
        .map((b) => String((b && (b.selection || b.runner)) || ""))
        .filter(Boolean),
    ),
  ];
  const exact = sels.find((s) => key(s) === want);
  if (exact) return exact;
  const wt = toks(name);
  const cand = sels.filter((s) => {
    const st = toks(s);
    return (
      st.length === wt.length &&
      wt.every((t, i) => st[i].startsWith(t) || t.startsWith(st[i]))
    );
  });
  return cand.length === 1 ? cand[0] : name;
}
function editCurrentPositionView(account) {
  account = account || selectedEditAccount();
  const username = account.username;
  const inScope = stmtScopeMatcher({ userId: account.id, downline: true });
  if (
    posSummaryMode() &&
    account.id &&
    Date.now() - ((state._betsUnderAt || {})[String(account.id)] || 0) > 1e4 &&
    state._betsUnderLoading !== String(account.id)
  ) {
    state._betsUnderLoading = String(account.id);
    refreshBetsFromApi({ under: String(account.id) })
      .catch(() => {})
      .finally(() => {
        state._betsUnderLoading = null;
        render();
      });
  }
  const activeBets = (state.bets || []).filter(
    (b) => b.status === "active" && (inScope(b.userId) || b.user === username),
  );
  const isDealerView = account.role === "company" || isDealerRole(account.role);
  const treeAccounts = isDealerView ? bookTreeAccounts() : [];
  const treeViewer = {
    id: String(account.id),
    share: account.role === "company" ? 100 : Number(account.share) || 0,
  };
  const netOf = (bets, runners) =>
    isDealerView
      ? BPBookTree.total({
          accounts: treeAccounts,
          bets,
          viewer: treeViewer,
          width: runners.length,
          fullPnl: false,
          positions: (bs) => runners.map((r) => BPBook.positionIfWins(bs, r)),
        })
      : runners.map((r) => BPBook.positionIfWins(bets, r));
  const oneNet = (name, bets) => Math.round(netOf(bets, [name])[0]);
  const scenarioRows = (bets, totalRunners) => {
    const base = BPBook.scenarioPositions(bets, totalRunners);
    const vals = netOf(
      bets,
      base.map((r) => (r.other ? null : r.runner)),
    );
    return base.map((r, i) => [r.runner, Math.round(vals[i])]);
  };
  const sessionNet = (bets) => {
    if (!isDealerView) return BPBook.sessionBook(bets);
    const t = BPBookTree.total({
      accounts: treeAccounts,
      bets,
      viewer: treeViewer,
      width: 2,
      fullPnl: false,
      positions: (bs) => {
        const k = BPBook.sessionBook(bs);
        return [k.yes, k.no];
      },
    });
    return { yes: Math.round(t[0]), no: Math.round(t[1]) };
  };
  const RACING_RX = /^(7|4339)-/;
  const events = new Map();
  activeBets.forEach((bet) => {
    const isFancy =
      bet.isFancy || String(bet.market || "").toLowerCase() === "fancy";
    const eventId = String(bet.eventId || bet.event || "");
    const rawName = bet.event;
    const eventName =
      rawName && !/^\d+$/.test(String(rawName))
        ? rawName
        : cricketEventNameById(eventId) || eventId;
    if (!events.has(eventId)) {
      events.set(eventId, {
        eventId,
        eventName,
        sport: bet.sport || sportLabelForEvent(eventName) || "Cricket",
        racing: RACING_RX.test(eventId),
        matchOdds: [],
        markets: new Map(),
        fancyBets: new Map(),
      });
    }
    const ev = events.get(eventId);
    if (isFancy) {
      const session = bet.selection || bet.runner || "Fancy";
      if (!ev.fancyBets.has(session)) ev.fancyBets.set(session, []);
      ev.fancyBets.get(session).push(bet);
      return;
    }
    const label = String(bet.marketLabel || "").trim();
    const sideish =
      /tied|completed|to be placed|over\/?under|goals?\b|toss|set\s*\d+\s*winner|correct\s*score|draw\s*no\s*bet|\bline\b/i.test(
        label,
      );
    const bookish = /book/i.test(String(bet.market || bet.marketType || ""));
    const mtype = String(bet.marketType || bet.market || "").toLowerCase();
    const ownMarketType = mtype !== "" && mtype !== "match_odds";
    if (!sideish && !bookish && !ev.racing && !ownMarketType) {
      ev.matchOdds.push(bet);
      return;
    }
    const _pm = positionMarketOf(bet);
    const key = String(_pm.marketId || label || bet.market || "mkt");
    if (!ev.markets.has(key))
      ev.markets.set(key, {
        label: _pm.label || label || prettyMarketName(bet.market) || "Market",
        bets: [],
        runners: Number(bet.runners) || 0,
        bookish,
      });
    ev.markets.get(key).bets.push(bet);
  });
  const cell = (v) =>
    v == null
      ? ""
      : `<span class="np-num ${v < 0 ? "neg" : "pos"}">${formatMoney(v)}</span>`;
  const moCell = (name, v) =>
    v == null
      ? ""
      : `<span class="np-team">${escapeHtml(String(name || ""))}</span>${cell(v)}`;
  const evLink = (ev) =>
    `<a class="np-event-link" href="${matchWinUrl(ev.eventId, ev.sport)}" onclick="${attrJs(`openMatch(${JSON.stringify(ev.eventName)},${JSON.stringify(ev.sport)},${JSON.stringify(ev.eventId)})`)}">${escapeHtml(ev.eventName)}</a>`;
  let body = "";
  let anyLeft = false;
  let anyFancy = false;
  let racingBody = "";
  events.forEach((ev) => {
    if (ev.racing) {
      const rows = [];
      ev.markets.forEach((m) => {
        scenarioRows(m.bets, m.runners || null).forEach((r) => rows.push(r));
      });
      if (!rows.length) return;
      racingBody += `<tr class="np-race"><td colspan="4">${evLink(ev)}</td></tr>`;
      for (let i = 0; i < rows.length; i += 2) {
        const a = rows[i];
        const b = rows[i + 1];
        racingBody +=
          `<tr class="np-row"><td class="np-runner">${escapeHtml(String(a[0]))}</td><td>${cell(a[1])}</td>` +
          (b
            ? `<td class="np-runner">${escapeHtml(String(b[0]))}</td><td>${cell(b[1])}</td>`
            : "<td></td><td></td>") +
          "</tr>";
      }
      return;
    }
    const evAllBets = [
      ...ev.matchOdds,
      ...[...ev.markets.values()].reduce((a, m) => a.concat(m.bets), []),
    ];
    const hasDrawOutcome =
      /soccer|football/i.test(ev.sport) ||
      evAllBets.some((b) =>
        /\b(the\s+)?draw\b|\btied?\b/i.test(
          String((b && (b.selection || b.runner)) || ""),
        ),
      );
    const left = [];
    if (ev.matchOdds.length) {
      const { team1: rawT1, team2: rawT2 } = eventTeams(ev.eventName);
      const team1 = resolveRunnerName(rawT1, ev.matchOdds),
        team2 = resolveRunnerName(rawT2, ev.matchOdds);
      const drawBet = ev.matchOdds.find((b) =>
        /draw|tie/i.test(b.selection || ""),
      );
      const hasDraw = hasDrawOutcome;
      const drawName = drawBet ? drawBet.selection : "The Draw";
      left.push({
        label: "Match Odds",
        c1: moCell(team1, oneNet(team1, ev.matchOdds)),
        cx: hasDraw ? moCell(drawName, oneNet(drawName, ev.matchOdds)) : "-",
        c2: moCell(team2, oneNet(team2, ev.matchOdds)),
      });
    }
    const evTeams = eventTeams(ev.eventName);
    const evT1 = resolveRunnerName(evTeams.team1, evAllBets),
      evT2 = resolveRunnerName(evTeams.team2, evAllBets);
    const EXOTIC_RX =
      /correct\s*score|top\s*(bat|bowl)|man\s*of\s*the\s*match|method|highest|fall\s*of/i;
    const outcomes = hasDrawOutcome ? 3 : 2;
    ev.markets.forEach((m) => {
      const teamish = m.bookish && !EXOTIC_RX.test(String(m.label || ""));
      const TWO_WAY_RX =
        /over\/?\s*under|\bgoals?\b|tied\s*match|completed\s*match|odd\s*\/?\s*even/i;
      const twoWay =
        !EXOTIC_RX.test(String(m.label || "")) &&
        TWO_WAY_RX.test(String(m.label || ""));
      const total =
        Number(m.runners) ||
        (teamish ? outcomes : 0) ||
        (twoWay ? 2 : 0) ||
        null;
      const sc = scenarioRows(m.bets, total);
      if (
        teamish &&
        hasDrawOutcome &&
        sc.length === 3 &&
        /^other$/i.test(String(sc[2][0]))
      )
        sc[2][0] = "The Draw";
      if (
        teamish &&
        !hasDrawOutcome &&
        sc.length === 2 &&
        /^other$/i.test(String(sc[1][0]))
      ) {
        const first = String(sc[0][0] || "");
        const same = (a, b) =>
          String(a || "")
            .trim()
            .toLowerCase() ===
          String(b || "")
            .trim()
            .toLowerCase();
        const otherTeam = same(first, evT1)
          ? evT2
          : same(first, evT2)
            ? evT1
            : "";
        if (otherTeam) sc[1][0] = otherTeam;
      }
      if (sc.length === 2 && /^other$/i.test(String(sc[1][0]))) {
        const first = String(sc[0][0]);
        if (/^over\s/i.test(first)) sc[1][0] = first.replace(/^over/i, "Under");
        else if (/^under\s/i.test(first))
          sc[1][0] = first.replace(/^under/i, "Over");
      }
      left.push({
        label: m.label,
        c1: sc[0] ? moCell(sc[0][0], sc[0][1]) : "",
        cx: sc[2] ? moCell(sc[2][0], sc[2][1]) : "-",
        c2: sc[1] ? moCell(sc[1][0], sc[1][1]) : "",
      });
    });
    const fancyRows = [...ev.fancyBets.entries()].map(
      ([session, sessBets]) => ({ session, ...sessionNet(sessBets) }),
    );
    if (!left.length && !fancyRows.length) return;
    if (left.length) anyLeft = true;
    if (fancyRows.length) anyFancy = true;
    body += `<tr class="np-event"><td colspan="7">${evLink(ev)}</td></tr>`;
    const rowCount = Math.max(left.length, fancyRows.length, 1);
    for (let i = 0; i < rowCount; i++) {
      const Lrow = left[i];
      const lHtml = Lrow
        ? `<td class="np-mkt">${escapeHtml(Lrow.label)}</td><td>${Lrow.c1}</td><td>${Lrow.cx}</td><td>${Lrow.c2}</td>`
        : "<td></td><td></td><td></td><td></td>";
      const f = fancyRows[i];
      const rHtml = f
        ? `<td class="np-mkt">${escapeHtml(f.session)}</td><td>${cell(f.yes)}</td><td>${cell(f.no)}</td>`
        : "<td></td><td></td><td></td>";
      body += `<tr class="np-row">${lHtml}${rHtml}</tr>`;
    }
  });
  const CASINO_RECENT_MS = 30 * 60 * 1e3;
  const casinoNow = Date.now();
  const casinoAll = (state.exAllBets || []).filter(
    (b) => b && inScope(b.userId),
  );
  const casinoGames = new Map();
  casinoAll.forEach((b) => {
    const placed = Date.parse(b.placedAt || "") || 0;
    const isOpen = String(b.status || "").toLowerCase() === "open";
    const isRecent = placed && casinoNow - placed < CASINO_RECENT_MS;
    if (!isOpen && !isRecent) return;
    const name = String(b.gameName || b.slug || "Casino");
    if (!casinoGames.has(name))
      casinoGames.set(name, {
        name,
        openStake: 0,
        bets: 0,
        stake: 0,
        pnl: 0,
        users: new Set(),
      });
    const g = casinoGames.get(name);
    g.users.add(String(b.bettor || b.userId || ""));
    if (isOpen) g.openStake += Number(b.stake) || 0;
    if (isRecent) {
      g.bets += 1;
      g.stake += Number(b.stake) || 0;
      if (!isOpen) g.pnl += Number(b.pnl) || 0;
    }
  });
  const casinoRows = isBetproOwner()
    ? [...casinoGames.values()].sort(
        (a, b) => b.openStake - a.openStake || b.stake - a.stake,
      )
    : [];
  const casinoCard = casinoRows.length
    ? `<table class="table exposure-table np-table np-casino">
        <thead><tr><th>${escapeHtml(T("Casino"))}</th><th>Khula (risk)</th><th>Bets</th><th>Stake</th><th>P/L</th></tr></thead>
        <tbody>${casinoRows
          .map(
            (g) => `<tr class="np-row">
          <td class="np-mkt">${escapeHtml(g.name)}${g.users.size > 1 ? ` <small>(${g.users.size} users)</small>` : ""}</td>
          <td>${g.openStake ? `<span class="np-num neg">${money(g.openStake)}</span>` : "-"}</td>
          <td>${g.bets || "-"}</td>
          <td>${g.stake ? money(g.stake) : "-"}</td>
          <td>${cell(g.pnl)}</td>
        </tr>`,
          )
          .join("")}</tbody>
      </table>`
    : "";
  const racingCard = racingBody
    ? `<table class="table exposure-table np-table np-racing">
        <thead><tr><th>${escapeHtml(T("col:Runner"))}</th><th>${escapeHtml(T("col:Stake"))}</th><th>${escapeHtml(T("col:Runner"))}</th><th>${escapeHtml(T("col:Stake"))}</th></tr></thead>
        <tbody>${racingBody}</tbody>
      </table>`
    : "";
  return `<section class="card net-exposure-card">
    <div class="plain-card-header"><strong>Net Exposure</strong> <button class="btn btn-primary btn-sm" onclick="refreshBetsFromApi().then(render)">Refresh</button></div>
    <div class="card-body">
      <table class="table exposure-table np-table${anyFancy ? "" : " np-no-right"}${anyLeft ? "" : " np-no-left"}">
        <thead><tr><th></th><th>1</th><th>X</th><th>2</th><th></th><th>Over/Yes</th><th>Under/No</th></tr></thead>
        <tbody>${body || (casinoCard ? "" : `<tr><td colspan="7" class="np-empty">${escapeHtml(T("No data available in table"))}</td></tr>`)}</tbody>
      </table>
      ${racingCard}
      ${casinoCard}
    </div>
  </section>`;
}
