function stmtFitColumns() {
  const tbl = document.querySelector("table.stmt-resp");
  if (!tbl) return;
  const ths = [...tbl.querySelectorAll("thead th")];
  if (!ths.length) return;
  const cellsByCol = (i) =>
    tbl.querySelectorAll(
      `tr.stmt-row td[data-col="${i}"], thead th[data-col="${i}"]`,
    );
  ths.forEach((_, i) =>
    cellsByCol(i).forEach((el) => el.classList.remove("stmt-hide")),
  );
  tbl.classList.add("stmt-measuring");
  const widths = ths.map((th) => th.getBoundingClientRect().width);
  tbl.classList.remove("stmt-measuring");
  const avail = (tbl.parentElement || tbl).clientWidth || tbl.clientWidth;
  let sum = 0;
  const hidden = new Set();
  widths.forEach((w, i) => {
    sum += w;
    if (i > 0 && sum > avail) hidden.add(i);
  });
  ths.forEach((_, i) => {
    if (hidden.has(i))
      cellsByCol(i).forEach((el) => el.classList.add("stmt-hide"));
  });
  tbl.querySelectorAll("tr.stmt-child li").forEach((li) => {
    li.hidden = !hidden.has(Number(li.getAttribute("data-col")));
  });
}
