function bpCollectOddsCells(container) {
  const out = [];
  if (!container) return out;
  container
    .querySelectorAll(".cricket-market-row, .odds-row, .race-row")
    .forEach((row) => {
      const blockEl = row.closest(
        ".cricket-market-block, .cricket-fancy-block, section",
      );
      const blockTitleEl =
        blockEl &&
        blockEl.querySelector(
          ".cricket-market-title strong, .fancy-title strong, h3",
        );
      const blockKey = (
        (blockTitleEl && blockTitleEl.textContent) ||
        ""
      ).trim();
      const labelEl =
        row.querySelector(".runner-name, .combined-label, .event-name") ||
        row.querySelector("strong");
      const label = ((labelEl && labelEl.textContent) || "").trim();
      let bi = 0,
        li = 0;
      row
        .querySelectorAll("button.back, button.lay, .odd-cell")
        .forEach((el) => {
          if (
            el.classList.contains("blank") ||
            el.classList.contains("disabled")
          )
            return;
          const isLay = el.classList.contains("lay");
          const idx = isLay ? li++ : bi++;
          const priceEl = el.querySelector("span, strong");
          const sizeEl = el.querySelector("small");
          const price = ((priceEl && priceEl.textContent) || "").trim();
          const size = ((sizeEl && sizeEl.textContent) || "").trim();
          if (!price && !size) return;
          out.push({
            el,
            sizeEl,
            key: blockKey + "|" + label + "|" + (isLay ? "L" : "B") + "|" + idx,
            price,
            size,
          });
        });
    });
  return out;
}
function bpFlashOddsChanges(container, prevMap) {
  const cells = bpCollectOddsCells(container);
  const next = new Map();
  cells.forEach((c) => {
    next.set(c.key, { price: c.price, size: c.size });
    const before = prevMap && prevMap.get(c.key);
    if (!before) return;
    if (before.price !== c.price && before.price && c.price) {
      c.el.classList.add("odds-blink");
      setTimeout(() => c.el.classList.remove("odds-blink"), 100);
    }
    if (before.size !== c.size && before.size && c.size && c.sizeEl) {
      c.sizeEl.classList.add("odds-blink-vol");
      setTimeout(() => c.sizeEl.classList.remove("odds-blink-vol"), 100);
    }
  });
  return next;
}
