function captureActiveInput() {
  try {
    const el = document.activeElement;
    if (!el || !/^(INPUT|TEXTAREA|SELECT)$/.test(el.tagName)) return null;
    if (
      el.tagName === "INPUT" &&
      !["number", "text", "search", "tel", "password", ""].includes(
        String(el.type || "").toLowerCase(),
      )
    )
      return null;
    const sel = inputSelector(el);
    if (!sel) return null;
    const nodes = Array.from(document.querySelectorAll(sel));
    let start = null,
      end = null;
    try {
      start = el.selectionStart;
      end = el.selectionEnd;
    } catch {}
    return {
      sel,
      index: Math.max(0, nodes.indexOf(el)),
      value: el.value,
      start,
      end,
    };
  } catch {
    return null;
  }
}
function inputSelector(el) {
  const tag = el.tagName.toLowerCase();
  if (el.id) return `#${CSS.escape(el.id)}`;
  if (el.name) return `${tag}[name="${CSS.escape(el.name)}"]`;
  if (el.className && el.className.trim())
    return `${tag}.${el.className
      .trim()
      .split(/\s+/)
      .map((c) => CSS.escape(c))
      .join(".")}`;
  return null;
}
function restoreActiveInput(p) {
  if (!p) return;
  try {
    const nodes = Array.from(document.querySelectorAll(p.sel));
    const el = nodes[p.index] || nodes[0];
    if (!el) return;
    if (el.value !== p.value) el.value = p.value;
    el.focus({ preventScroll: true });
    if (p.start != null && el.setSelectionRange) {
      try {
        el.setSelectionRange(p.start, p.end);
      } catch {}
    } else if (
      p.start == null &&
      String(el.type || "").toLowerCase() === "number" &&
      el.value !== ""
    ) {
      try {
        el.type = "text";
        const n = el.value.length;
        el.setSelectionRange(n, n);
      } catch {
      } finally {
        try {
          el.type = "number";
        } catch {}
      }
    }
  } catch {}
}
